/* PN Weekly v10.0 — JavaScript รวมไฟล์เดียว
หมวด 1 กติกาข้อมูล / 2 รายงาน PDF–Excel / 3 ภาพ JPG / 4 ข้อมูลพื้นฐาน
หมวด 5 จัดเก็บในเครื่อง / 6 Supabase / 7 หน้าจอและการทำงาน
ไม่มีข้อมูลสัญญาจริง • มีค่าเริ่มต้น URL/anon key สาธารณะที่ผู้ใช้ระบุ */

// ==================== 1. DATA MODEL AND BUSINESS RULES ====================
export const clone=o=>JSON.parse(JSON.stringify(o));
// Import history is immutable during ordinary edits and can be several MB.
export function cloneForMutation(s){const {importHistory,...active}=s;return {...clone(active),...(importHistory===undefined?{}:{importHistory})};}
export function workspaceChanges(before,after){
 const collections={},values={};
 for(const k of ['projects','reports','contractRegistry','categories','contractors','supervisors','workTypes','workNames','workCodes','budgetAccounts','fundingSources']){
  const old=new Map((before[k]||[]).map(x=>[x.id,x])),now=new Map((after[k]||[]).map(x=>[x.id,x]));
  const upsert=[...now.values()].filter(x=>!x._unloaded&&old.get(x.id)!==x&&JSON.stringify(old.get(x.id))!==JSON.stringify(x));const remove=[...old.keys()].filter(id=>!now.has(id));
  if(upsert.length||remove.length)collections[k]={upsert,remove};
 }
 const settings=Object.fromEntries(Object.entries(after.settings||{}).filter(([key,value])=>JSON.stringify(before.settings?.[key])!==JSON.stringify(value)));if(Object.keys(settings).length)values.settings=settings;
 for(const k of ['years','yearCodes','masterSequences','issues'])if(JSON.stringify(before[k])!==JSON.stringify(after[k])&&after[k]!==undefined)values[k]=after[k];
 return {collections,values};
}
export function validateLoadedWorkspace(s){if(!s?.loadedScope)return validateBackup(s);const reports=s.reports.filter(r=>!r._unloaded);return validateBackup({...s,reports:reports.length?reports:[{id:'EMPTY',entries:{},snapshots:{},locked:true,imported:true}]});}
const qualityCache=new WeakMap();
export function qualityIssues(s,year,funding){const key=year+'|'+funding,cached=qualityCache.get(s);if(cached?.has(key))return cached.get(key);const result=computeQualityIssues(s,year,funding);const cache=cached||new Map();cache.set(key,result);qualityCache.set(s,cache);return result;}
function computeQualityIssues(s,year,funding){const rows=[],gaps=new Map();const scoped=s.reports.filter(r=>reportMatchesScope(s,r,year,funding));const periods=new Map();
 for(const r of scoped){const key=r.start+'|'+r.end;if(r.start&&r.end){if(periods.has(key))rows.push({type:'รอบวันที่ซ้ำตามต้นฉบับ',label:r.title,reportId:r.id,evidence:[r.start,r.end]});else periods.set(key,r.id);if(days(r.end,r.start)!==6||new Date(r.end+'T00:00:00Z').getUTCDay()!==1)rows.push({type:'ช่วงรายงานต้องตรวจสอบ',label:r.title,reportId:r.id,evidence:[r.start,r.end]});}
  for(const [id,e]of missingPaymentDates(r)){const p=projectAt(s,r,id);const key=p?.contract||id,existing=gaps.get(key);if(existing){existing.count++;existing.evidence.push([r.id,e.payment,e.paymentDate||'',e.note||'']);}else gaps.set(key,{type:'วันที่เบิกจ่ายไม่ครบ',label:key,reportId:r.id,count:1,evidence:[[r.id,e.payment,e.paymentDate||'',e.note||'']]});}
 }
 for(const x of gaps.values())rows.push({...x,label:x.label+' · พบใน '+x.count+' รายงาน'});
 for(const r of s.contractRegistry||[])if(!r.deletedAt&&r.year===year&&(r.funding||'DOH')===funding&&(!r.contractorId||r.contractorNeedsReview))rows.push({type:'ผู้รับจ้างรอตรวจสอบ',label:r.contract+' · '+r.title,registryId:r.id,evidence:[r.contractorRaw||'',r.contractorId||'',!!r.contractorNeedsReview]});
 return rows;
}
export const missingPaymentDates=r=>r._missingPaymentDates||Object.entries(r.entries||{}).filter(([,e])=>e.payment==='เบิกจ่ายแล้ว'&&!e.paymentDate);
export function reportMatchesScope(s,r,year,funding){if(r.id==='EMPTY'||(r.funding||'DOH')!==funding)return false;if(r.year)return r.year===year;return Object.keys(r.entries||{}).some(id=>(r.snapshots?.[id]||s.projects.find(p=>p.id===id))?.year===year);}

export const uid=()=>globalThis.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=(globalThis.crypto?.getRandomValues?.(new Uint8Array(1))[0]??Math.random()*16)&15;return(c==='x'?r:(r&3|8)).toString(16);});
export const iso=d=>new Date(d).toISOString().slice(0,10);
export const addDays=(d,n)=>iso(Date.parse(d+'T00:00:00Z')+n*86400000);
export const days=(a,b)=>Math.round((Date.parse(a+'T00:00:00Z')-Date.parse(b+'T00:00:00Z'))/86400000);
export const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export function rangeFor(date,mode='tue'){let dow=new Date(date+'T00:00:00Z').getUTCDay();let monday=addDays(date,-((dow+6)%7));return mode==='tue'?{start:addDays(monday,-6),end:monday,reference:monday}:{start:monday,end:addDays(monday,6),reference:monday};}
export const complete=e=>Number(e.actual)===100;
export const elapsed=(p,e,reference)=>complete(e)?'-':Math.max(0,days(reference,p.start)+1);
export const effectiveDays=p=>p.duration+p.extensions.filter(e=>e.approved).reduce((n,e)=>n+e.days,0);
export const effectiveEnd=p=>[p.end,p.originalEnd?addDays(p.originalEnd,(p.extensions||[]).filter(e=>e.approved).reduce((n,e)=>n+e.days,0)):''].filter(Boolean).sort().at(-1)||'';
export const expired=(p,date=today())=>!!effectiveEnd(p)&&date>effectiveEnd(p);
export const entryFor=(report,id)=>report.entries[id]||{plan:0,weekly:0,actual:0,note:'',payment:'รอส่งมอบงาน',confirmed:false};
export function validateEntry(e,previous){for(const k of ['plan','weekly','actual'])if(!Number.isFinite(Number(e[k]))||Number(e[k])<0||Number(e[k])>100)throw Error('เปอร์เซ็นต์ต้องเป็นตัวเลขระหว่าง 0–100');if(previous&&Number(e.actual)<Number(previous.actual))throw Error('ผลงานสะสมลดลงจากรอบก่อน กรุณาตรวจสอบ');if(previous&&Math.abs(Number(e.actual)-Number(previous.actual)-Number(e.weekly))>.011)throw Error('ผลงานสะสมต้องเท่ากับผลงานสะสมรอบก่อน + ผลงานรายสัปดาห์');if(e.payment&&!['รอส่งมอบงาน','รอเบิกจ่าย','เบิกจ่ายแล้ว'].includes(e.payment))throw Error('สถานะเบิกจ่ายไม่ถูกต้อง');if(e.payment==='เบิกจ่ายแล้ว'&&!complete(e))throw Error('เบิกจ่ายแล้วต้องมีผลงานสะสม 100%');}
export function projectAt(state,report,id){const p=report.snapshots?.[id]||state.projects.find(p=>p.id===id);if(!p)return p;const names=effectiveReportNames(state,report,p);return {...p,title:names.title||p.title,supervisor:names.supervisor??p.supervisor};}
export function rowsFor(state,report,year){return Object.keys(report.entries).map(id=>({p:projectAt(state,report,id),e:report.entries[id]})).filter(x=>x.p&&(!year||x.p.year===Number(year))&&(!state.activeFunding||(x.p.funding||'DOH')===state.activeFunding)).sort(sortRows);}
export function createReport(state,range,year,funding='DOH'){if(days(range.end,range.start)!==6)throw Error('รอบรายงานต้องมี 7 วัน');if(range.reference!==range.end||new Date(range.end+'T00:00:00Z').getUTCDay()!==1)throw Error('รอบอังคาร–จันทร์ต้องสิ้นสุดวันจันทร์และใช้วันท้ายรอบคำนวณ');if(state.reports.some(r=>r.start===range.start&&r.year===year&&(r.funding||'DOH')===funding&&!r.imported))throw Error('มีรอบรายงานนี้ในปีงบประมาณที่เลือกแล้ว');if(state.contractRegistry||state.projects.some(p=>p.contract))linkRegistryForReport(state,year,funding);const candidates=state.reports.filter(r=>(!r.year||r.year===year)&&(r.funding||'DOH')===funding&&r.end&&r.end<range.start).sort((a,b)=>b.end.localeCompare(a.end));const entries={};for(const p of state.projects.filter(p=>!p.deletedAt&&p.year===year&&(p.funding||'DOH')===funding)){const prev=candidates.find(r=>r.entries[p.id]);const carried=state.loadedScope?.latestEntries?.[p.id];const e=prev?entryFor(prev,p.id):carried&&state.loadedScope?.funding===funding&&state.loadedScope?.year===year&&state.reports.filter(r=>(r.funding||'DOH')===funding&&(!r.year||r.year===year)).every(r=>!r.end||r.end<range.start)?carried:{...entryFor({entries:{}},p.id),deliveryDate:state.contractRegistry?.find(x=>x.projectId===p.id)?.deliveryDate||'',acceptanceDate:state.contractRegistry?.find(x=>x.projectId===p.id)?.acceptanceDate||'',paymentDate:state.contractRegistry?.find(x=>x.projectId===p.id)?.finalPaymentDate||''};entries[p.id]={...clone(e),paymentDate:e.paymentDate||parsePaymentDate(e.note)||state.contractRegistry?.find(x=>x.projectId===p.id)?.finalPaymentDate||'',weekly:0,confirmed:false};const reg=state.contractRegistry?.find(x=>x.projectId===p.id);if(reg){for(const [target,key]of [['note','note'],['deliveryDate','deliveryDate'],['acceptanceDate','acceptanceDate'],['paymentDate','finalPaymentDate'],['payment','payment']])if(reg[key]!==undefined)entries[p.id][target]=reg[key];}}if(!Object.keys(entries).length)throw Error('ไม่มีสัญญาในปีงบประมาณที่เลือก');return {id:'RPT-'+range.end+'-'+year+'-'+funding,title:'สัปดาห์ที่ '+nextWeek(state,year,funding),funding,year,...range,locked:false,imported:false,entries,snapshots:{},createdAt:new Date().toISOString()};}
export function validateProject(p,state,ignoreId){if(!p.title.trim()||!p.contract.trim()||!p.start||!p.end||!p.contractor.trim())throw Error('กรอกข้อมูลงาน สัญญา หมวดหมู่ วันที่ และผู้รับจ้างให้ครบ');if(p.end<p.start)throw Error('วันสิ้นสุดสัญญาต้องไม่น้อยกว่าวันเริ่มต้น');if(!Number.isInteger(p.duration)||p.duration<=0)throw Error('ระยะเวลาดำเนินการต้องเป็นจำนวนเต็มมากกว่า 0');if(state.projects.some(x=>x.id!==ignoreId&&x.year===p.year&&x.contract===p.contract&&(x.funding||'DOH')===(p.funding||'DOH')))throw Error('เลขสัญญานี้มีอยู่แล้วในปีงบประมาณเดียวกัน');}

export const sortRows=(a,b)=>Number(complete(a.e))-Number(complete(b.e))||Number(a.p.year)-Number(b.p.year)||parseInt(contractKey(a.p.contract))-parseInt(contractKey(b.p.contract))||contractKey(a.p.contract).localeCompare(contractKey(b.p.contract),'th',{numeric:true});
const stableId=(prefix,name)=>{let h=2166136261;for(const c of name)h=Math.imul(h^c.charCodeAt(0),16777619);return prefix+'-'+(h>>>0).toString(16);};
export function normalizeState(s){
 s.projects||=[];s.reports||=[];s.categories||=[];s.years||=[];s.settings||={};s.audit||=[];
 s.contractRegistry||=[];s.contractors||=[];s.supervisors||=[];s.workTypes||=[];s.workNames||=[];
 s.fundingSources||=[{id:'DOH',name:'กรมทางหลวง'},{id:'PROVINCE',name:'งบจังหวัด'}];
 const maps={},byId={};const getMap=k=>maps[k]??=new Map(s[k].map(x=>[x.name,x])),getById=k=>byId[k]??=new Map(s[k].map(x=>[x.id,x]));
 const add=(key,name,prefix,preferredId)=>{name=String(name||'').trim();if(!name)return '';const m=getMap(key),idMap=getById(key);let v=m.get(name)||(preferredId&&idMap.get(preferredId));if(!v){v={id:preferredId||stableId(prefix,name),name,archived:false};if(key==='workNames')v.typeId='';s[key].push(v);m.set(name,v);idMap.set(v.id,v);}return v.id;};
 for(const p of s.projects){p.funding||='DOH';if(!p.registryId)p.contractorId=add('contractors',p.contractor,'CTR',p.contractorId);else if(p.contractorId&&!getById('contractors').has(p.contractorId))p.contractorId=add('contractors',p.contractor,'CTR',p.contractorId);if(p.registryId){if(!p.supervisorId||!getById('supervisors').has(p.supervisorId))p.supervisorId='';}else p.supervisorId=add('supervisors',p.supervisor,'SUP',p.supervisorId);p.workNameId=add('workNames',p.title,'JOB',p.workNameId);if(p.workTypeId&&!getById('workTypes').has(p.workTypeId))p.workTypeId='';p.workTypeId||='';if(Number.isInteger(+p.year)&&+p.year>=2500&&!s.years.includes(+p.year))s.years.push(+p.year);}
 for(const r of s.reports){if(r&&r.id!=='EMPTY'&&Number.isInteger(+r.year)&&+r.year>=2500&&!s.years.includes(+r.year))s.years.push(+r.year);}
 if(s.years.length>1)s.years.sort((a,b)=>a-b);
 if(s.projects.some(p=>p.category==='UNCATEGORIZED')&&!s.categories.some(c=>c.id==='UNCATEGORIZED'))s.categories.push({id:'UNCATEGORIZED',name:'ยังไม่ระบุหมวดเดิม'});
 s.settings.reportTitles||={DOH:s.settings.title||'รายงานความก้าวหน้างาน พรบ.',PROVINCE:'รายงานความก้าวหน้างานงบจังหวัด'};s.settings.systemName||='PN Weekly';s.settings.logo||='';if(!/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(s.settings.logo))s.settings.logo='';
 ensureRegistry(s);syncRoadMasters(s);for(const r of s.contractRegistry)if(Number.isInteger(+r.year)&&+r.year>=2500&&+r.year<=2700&&!s.years.includes(+r.year))s.years.push(+r.year);s.years.sort((a,b)=>a-b);assignMasterCodes(s);for(const key of Object.keys(masterLabels))if(key!=='years')for(const item of s[key]||[])delete item.archived;for(const item of [...s.projects,...s.contractRegistry])delete item.archived;return s;
}
export function paymentNote(e){if(e.payment==='เบิกจ่ายแล้ว'&&e.paymentDate){const base='เบิกจ่ายแล้ว วันที่ '+new Date(e.paymentDate+'T00:00:00Z').toLocaleDateString('th-TH',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}),custom=String(e.note||'').replace(/^เบิกจ่ายแล้ว วันที่ [^·]*(?:·\s*)?/,'').trim();return base+(custom?' · '+custom:'');}return e.note||(complete(e)?e.payment:'');}
export const fundingName=(s,id)=>s.fundingSources?.find(x=>x.id===id)?.name||(id==='PROVINCE'?'งบจังหวัด':'กรมทางหลวง');
export function reportTitle(s,r,year){const cfg=r.settingsSnapshot||s.settings,group=s.activeFunding||r.funding||'DOH',title=cfg.reportTitles?.[group]||s.settings.reportTitles?.[group]||(group==='DOH'?cfg.title:'รายงานความก้าวหน้างานงบจังหวัด');return title.replace(/(?:พ\.?ศ\.?\s*)?25\d{2}|(?<=พรบ\.)\d{2}/g,'').trim()+' '+year+' · '+fundingName(s,group)+' '+cfg.organization+(r.locked?'':' (ฉบับร่าง)');}

export function parsePaymentDate(note){const m=String(note||'').match(/วันที่\s*(\d{1,2})\s+([^\s]+)\s+(\d{4})/);if(!m)return '';const months=['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];const month=months.indexOf(m[2]==='พฤภาคม'?'พฤษภาคม':m[2])+1;if(!month)return '';const date=String(+m[3]-543)+'-'+String(month).padStart(2,'0')+'-'+m[1].padStart(2,'0');return !Number.isNaN(Date.parse(date+'T00:00:00Z'))&&new Date(date+'T00:00:00Z').toISOString().slice(0,10)===date?date:'';}

function nextWeek(state,year,funding){const eligible=state.reports.filter(r=>(r.funding||'DOH')===funding&&(r.year===year||(!r.year&&Object.keys(r.entries).some(id=>state.projects.some(p=>p.id===id&&p.year===year)))));return Math.max(0,...eligible.map(r=>Number(String(r.title||'').match(/(?:รอบที่|สัปดาห์ที่)\s*(\d+)/)?.[1]||0)))+1;}

export const statusKey=e=>!complete(e)?'ongoing':e.payment==='เบิกจ่ายแล้ว'?'paid':e.payment==='รอเบิกจ่าย'?'pay':'deliver';
export function validateDates(e){for(const k of ['paymentDate','deliveryDate','acceptanceDate'])if(e[k]&&!/^\d{4}-\d{2}-\d{2}$/.test(e[k]))throw Error('รูปแบบวันที่ไม่ถูกต้อง');if(e.deliveryDate&&e.acceptanceDate&&e.acceptanceDate<e.deliveryDate)throw Error('วันที่ตรวจรับต้องไม่น้อยกว่าวันที่ส่งมอบ');if(e.acceptanceDate&&e.paymentDate&&e.payment==='เบิกจ่ายแล้ว'&&e.paymentDate<e.acceptanceDate)throw Error('วันที่เบิกจ่ายต้องไม่น้อยกว่าวันที่ตรวจรับ');}
export function amendReport(state,id,patch,at=new Date().toISOString()){
 const s=clone(state),r=s.reports.find(x=>x.id===id);if(!r)throw Error('ไม่พบรายงาน');const before=clone(r),affected=[];let any=false;
 const prior=(id,date)=>s.reports.filter(x=>x.id!==r.id&&x.end&&date&&x.end<date&&x.entries[id]).sort((a,b)=>b.end.localeCompare(a.end))[0]?.entries[id];
 for(const [pid,change]of Object.entries(patch)){const e=r.entries[pid];if(!e)throw Error('ไม่พบสัญญาในรายงาน');if(Object.keys(change).some(k=>!['plan','weekly','actual','note','payment','paymentDate','deliveryDate','acceptanceDate'].includes(k)))throw Error('ช่องแก้ไขไม่ถูกต้อง');const old=clone(e);Object.assign(e,change);const prev=prior(pid,r.start);const actualChanged=Number(e.actual)!==Number(old.actual),weeklyChanged=Number(e.weekly)!==Number(old.weekly);
 if(actualChanged||weeklyChanged){if(!r.start||!r.end)throw Error('รายงานไม่มีช่วงวันที่ จึงยังแก้เปอร์เซ็นต์ย้อนหลังไม่ได้');if(actualChanged)e.weekly=+(Number(e.actual)-Number(prev?.actual||0)).toFixed(2);else e.actual=+(Number(prev?.actual||0)+Number(e.weekly)).toFixed(2);validateEntry(e,prev||{actual:0});}
 validateEntry(e);validateDates(e);if(e.payment==='เบิกจ่ายแล้ว'&&e.paymentDate)e.note=paymentNote(e);else if(old.payment==='เบิกจ่ายแล้ว'&&e.payment!=='เบิกจ่ายแล้ว'&&e.note?.startsWith('เบิกจ่ายแล้ว วันที่ '))e.note='';
 if(JSON.stringify(e)!==JSON.stringify(old))any=true;
 if(Number(e.actual)!==Number(old.actual)){let prevActual=Number(e.actual);for(const next of s.reports.filter(x=>x.end&&x.end>r.end&&x.entries[pid]).sort((a,b)=>a.end.localeCompare(b.end))){const n=next.entries[pid],weekly=+(Number(n.actual)-prevActual).toFixed(2);if(weekly<0||weekly>100)throw Error('ผลงานสะสมใหม่มากกว่าสัปดาห์ถัดไป กรุณาตรวจผลงานสะสมให้สอดคล้องกัน');if(weekly!==Number(n.weekly)){n.weekly=weekly;next.modifiedAt=at;next.amendedVersion=(next.amendedVersion||0)+1;affected.push(next.id);}prevActual=Number(n.actual);}}
 }
 if(!any)throw Error('ยังไม่มีข้อมูลเปลี่ยนแปลง');r.modifiedAt=at;r.amendedVersion=(r.amendedVersion||0)+1;

 if(s.contractRegistry)for(const [pid,change]of Object.entries(patch)){const isLatest=!s.reports.some(later=>later.end>r.end&&later.entries?.[pid]);syncContractDates(s,pid,r.entries[pid],Object.keys(change).filter(k=>isLatest||!['note','payment'].includes(k)));}
 s.amendments||=[];s.amendments.unshift({id:uid(),reportId:id,at,beforeEntries:before.entries,afterEntries:clone(r.entries),affectedReports:[...new Set(affected)]});s.amendments=s.amendments.slice(0,100);
 s.audit.unshift({id:uid(),at,action:'แก้ไขรายงานย้อนหลัง '+r.title});return s;
}


// ==================== 2. PDF / EXCEL REPORTS ====================
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const fmt=d=>d?new Date(d+'T00:00:00Z').toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'ไม่ระบุ';
export const displayContract=value=>String(value||'').replace(/^\s*ป\s*\.?\s*น\s*\.?\s*/u,'').trim();
export const reportValues=(p,e,r)=>[displayContract(p.contract),p.title,fmt(p.start),fmt(p.end),effectiveDays(p),r.reference?elapsed(p,e,r.reference):'-',p.contractor,p.supervisor,+e.plan,+e.weekly,+e.actual,paymentNote(e)];
export const summaryRows=rows=>[['ผลงานแล้วเสร็จ 100 %',rows.filter(x=>complete(x.e)).length,''],['เบิกจ่ายแล้ว',rows.filter(x=>x.e.payment==='เบิกจ่ายแล้ว').length,'paid'],['รอเบิกจ่าย',rows.filter(x=>complete(x.e)&&x.e.payment==='รอเบิกจ่าย').length,'pay'],['รอส่งมอบงาน',rows.filter(x=>complete(x.e)&&x.e.payment==='รอส่งมอบงาน').length,'deliver'],['ยังไม่แล้วเสร็จ',rows.filter(x=>!complete(x.e)).length,'']];
