export function wrapped(ctx,text,width){if(String(text??'').includes('\n'))return String(text).split('\n').flatMap(t=>wrapped(ctx,t,width));const lines=[];let line='';for(const {segment}of new Intl.Segmenter('th',{granularity:'word'}).segment(String(text??''))){if(ctx.measureText(line+segment).width<=width){line+=segment;continue;}if(line.trim()){lines.push(line.trim());line='';}if(ctx.measureText(segment).width<=width){line=segment;continue;}for(const {segment:c}of new Intl.Segmenter('th',{granularity:'grapheme'}).segment(segment)){if(ctx.measureText(line+c).width>width&&line){lines.push(line);line='';}line+=c;}}if(line.trim())lines.push(line.trim());return lines.length?lines:[''];}
