 [[0,1,'สัญญาที่ ปน.'],[1,2,'งานจ้างเหมา'],[5,6,'ดำเนินการไปแล้ว (วัน)'],[6,7,'ผู้รับจ้าง'],[7,8,'ผู้ควบคุมงาน'],[11,12,'หมายเหตุ']].forEach(([l,rr,t])=>box(l,rr,y0,headerH,t,{head:true}));
