export function validateRegistryRelations(s){const people=new Set((s.supervisors||[]).map(p=>p.id)),sourceIds=new Set();for(const r of s.contractRegistry||[]){if(r.sourceId){const key=[r.year,r.funding||'DOH',String(r.sourceId).trim()].join('|');if(sourceIds.has(key))throw Error('ID Code ซ้ำในกลุ่มงบและปี: '+r.sourceId);sourceIds.add(key);}if(r.segments!==undefined&&(!Array.isArray(r.segments)||r.segments.some(x=>!x||typeof x!=='object'||Array.isArray(x))))throw Error('รูปแบบช่วงทางไม่ถูกต้อง: '+r.contract);for(const key of ['committeeIds','supervisorIds'])if(r[key]!==undefined){if(!Array.isArray(r[key])||new Set(r[key]).size!==r[key].length)throw Error('รายชื่อบุคลากรซ้ำหรือรูปแบบไม่ถูกต้อง: '+r.contract);for(const id of r[key])if(!people.has(id))throw Error('ไม่พบคีย์บุคลากรที่อ้างอิงในสัญญา '+r.contract+' กรุณานำเข้าข้อมูลบุคลากรให้ครบ');}if(r.personnelAssignments!==undefined){if(!Array.isArray(r.personnelAssignments)||r.personnelAssignments.some(a=>!a||typeof a!=='object'||typeof a.position!=='string'))throw Error('รูปแบบบุคลากรไม่ถูกต้อง');for(const group of ['inspection','supervision']){const rows=r.personnelAssignments.filter(a=>a.group===group).sort((a,b)=>a.ordinal-b.ordinal),ids=rows.map(a=>a.personId);if(rows.length&&rows.filter(a=>a.duty===(group==='inspection'?'ประธาน':'ผู้ควบคุมงาน')).length!==1)throw Error(group==='inspection'?'คณะกรรมการตรวจรับต้องมีประธานหนึ่งคน':'กลุ่มผู้ควบคุมต้องมีผู้ควบคุมงานหลักหนึ่งคน');if(JSON.stringify(ids)!==JSON.stringify(r[group==='inspection'?'committeeIds':'supervisorIds']||[]))throw Error('คีย์บุคลากรและรายการบทบาทไม่ตรงกัน');for(let i=0;i<rows.length;i++){const a=rows[i];if(!people.has(a.personId)||a.ordinal!==i+1||!(group==='inspection'?['ประธาน','กรรมการ']:['ผู้ควบคุมงาน','ผู้ช่วยผู้ควบคุมงาน']).includes(a.duty))throw Error('ลำดับหรือบทบาทบุคลากรไม่ถูกต้อง');}}if(r.personnelAssignments.some(a=>!['inspection','supervision'].includes(a.group)))throw Error('ประเภทบุคลากรไม่ถูกต้อง');}}return s;}

