export function dataChangeBadge(record){const change=record?.dataChange;if(record?.reviewedAt)return '';if(!['new','updated'].includes(change?.kind))return '';return `<button type="button" class="pill ${change.kind==='new'?'success':'info'}" data-change-kind="${change.kind}" data-review-record="${esc(record.id)}">${change.kind==='new'?'ข้อมูลใหม่':'อัปเดต'}${record.reviewedAt?' · ตรวจแล้ว':' · รอตรวจ'}</button>`;}
