 const fullMonths=['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];
 const mIdx=tok=>{if(!tok)return 0;const t=tok.trim().replace(/\.$/,'');let i=months.findIndex(m=>t.startsWith(m.replace(/\.$/,'')));if(i>=0)return i+1;i=fullMonths.findIndex(m=>t.startsWith(m));return i>=0?i+1:0;};
