 if((before===undefined||(before&&typeof before==='object'&&!Array.isArray(before)))&&(after===undefined||(after&&typeof after==='object'&&!Array.isArray(after)))){before=before||{};after=after||{};return [...new Set([...Object.keys(before),...Object.keys(after)])].filter(k=>!ignored.has(k)&&before[k]!==after[k]).flatMap(k=>importChanges(before[k],after[k],[...path,k]));}
