export function projectFromRegistry(s,r){const old=s.projects.find(p=>p.id===r.projectId);return {...clone(old||{}),id:r.projectId||'PN-'+r.id,registryId:r.id,contract:r.contract,year:r.year,funding:r.funding||'DOH',title:r.title,category:old?.category||'UNCATEGORIZED',start:r.start,end:r.end,originalEnd:r.originalEnd||old?.originalEnd||r.end,duration:+r.duration,extensions:clone(r.extensions||old?.extensions||[]),contractorId:r.contractorId||'',contractor:s.contractors?.find(x=>x.id===r.contractorId)?.name||r.contractorRaw||'',supervisorId:r.supervisorId||'',supervisor:r.personnelImported?personnelNames(s,r).map(shortSupervisor).join(' / '):s.supervisors?.find(x=>x.id===r.supervisorId)?.name||r.supervisor||'',workNameId:r.workNameId||'',workTypeId:r.workTypeId||'',workCodeId:r.workCodeId||'',budgetAccountId:r.budgetAccountId||'',extras:clone(r.extras||old?.extras||{}),archived:!!r.deletedAt};}
