export const masterLabels={contractors:'ผู้รับจ้าง',supervisors:'ผู้ควบคุมงาน',workTypes:'ประเภทงาน',workNames:'ชื่องาน',workCodes:'รหัสงาน',budgetAccounts:'บัญชีงบประมาณ',years:'ปีงบประมาณ'};
