export function assignMasterCodes(s){s.masterSequences||={};s.yearCodes||={};for(const [key,prefix]of Object.entries(masterPrefixes)){const items=key==='years'?(s.years||[]).map(y=>({id:String(y),code:s.yearCodes[y]})):(s[key]||[]);const re=new RegExp('^'+prefix+'(\\d{6})$');let seq=s.masterSequences[key]||0;const used=new Set();for(const item of items){const m=re.exec(item.code||'');if(m){const n=+m[1];if(n>seq)seq=n;used.add(item.code);}}for(const item of items){if(!re.test(item.code||'')){do{seq++;if(seq>999999)throw Error('รหัสข้อมูลเต็มในประเภท '+masterLabels[key]);item.code=prefix+String(seq).padStart(6,'0');}while(used.has(item.code));used.add(item.code);}if(key==='years')s.yearCodes[item.id]=item.code;}s.masterSequences[key]=seq;}return s;}
