function dashboard(){
 const rows=activeRows(),done=rows.filter(x=>complete(x.e)).length,paid=rows.filter(x=>statusKey(x.e)==='paid').length,ongoing=rows.filter(x=>statusKey(x.e)==='ongoing').length,pay=rows.filter(x=>statusKey(x.e)==='pay').length,deliver=rows.filter(x=>statusKey(x.e)==='deliver').length;
 const avg=k=>rows.length?rows.reduce((n,x)=>n+Number(x.e[k]||0),0)/rows.length:0,actual=avg('actual'),plan=avg('plan');
 const attention=rows.filter(x=>!complete(x.e)&&(expired(x.p)||Number(x.e.actual)<Number(x.e.plan))).sort((a,b)=>(Number(b.e.plan)-Number(b.e.actual))-(Number(a.e.plan)-Number(a.e.actual)));
 const hist=state.reports.filter(r=>reportMatchesScope(state,r,year,funding)&&Object.keys(r.entries||{}).length).sort((a,b)=>(b.end||b.reference||'').localeCompare(a.end||a.reference||'')).slice(0,6).reverse();
 const metric=(label,n,note,key,cls='')=>`<button class="dash-metric ${cls}" data-dashboard-status="${key}"><span class="dash-metric-label">${label}<span aria-hidden="true">${miniIcon('open')}</span></span><strong>${n.toLocaleString('th-TH')}<small>สัญญา</small></strong><span class="sub">${note}</span></button>`;
 return header('ภาพรวมโครงการ','ติดตามงานทาง · แขวงทางหลวงปัตตานี',`<button class="btn" data-action="preview">ดูรายงานฉบับเต็ม ${miniIcon('open')}</button><button class="btn primary" data-action="new-report">＋ สร้างสัปดาห์รายงาน</button>`)+periodBar()+`<div class="dashboard-shell"><section class="dash-hero"><div><span class="dash-kicker">ความก้าวหน้าประจำสัปดาห์ · ปี ${year}</span><h2>${esc(state.fundingSources.find(x=>x.id===funding)?.name||funding)}</h2><p>${rows.length?esc(weekLabel(report()))+' · '+fmt(report().start)+' – '+fmt(report().end):'ยังไม่มีรายงานในกลุ่มงบและปีที่เลือก'}</p><button class="hero-link" data-view="weekly">เปิดสัปดาห์รายงาน <span aria-hidden="true">→</span></button></div><div class="hero-progress"><div class="hero-progress-top"><span>ผลงานสะสมเฉลี่ย</span><strong>${actual.toFixed(2)}<small>%</small></strong></div><div class="hero-track"><span style="width:${Math.min(100,Math.max(0,actual))}%"></span></div><div class="hero-progress-bottom"><span>แผนเฉลี่ย ${plan.toFixed(2)}%</span><span>แล้วเสร็จ ${done} / ${rows.length} สัญญา</span></div><small>ค่าเฉลี่ยรายสัญญา ไม่ถ่วงน้ำหนักวงเงิน</small></div></section><div class="dash-metrics">${metric('สัญญาในรายงาน',rows.length,'ดูรายการทั้งหมด','all')}${metric('กำลังดำเนินการ',ongoing,'ติดตามแผนและผลงาน','ongoing','gold')}${metric('รอเบิกจ่าย',pay,'แล้วเสร็จและส่งมอบงานแล้ว','pay','blue')}${metric('เบิกจ่ายแล้ว',paid,'ตรวจรายละเอียดการเบิกจ่าย','paid','paid-metric')}${metric('หมดอายุสัญญา',registryVisibleRecords().filter(r=>registryExpired(state,r)).length,'เฉพาะงานยังไม่เสร็จ · ข้อมูลปัจจุบัน','expired','expired-metric')}</div><div class="dash-columns"><section class="card dash-trend"><div class="card-header"><div><h2>แผนและผลงานสะสม</h2><div class="sub">${hist.length} สัปดาห์ล่าสุด · กดแท่งกราฟเพื่อเปิดรายงาน</div></div><div class="legend"><span><i></i>แผน</span><span><i class="dark"></i>ผลงาน</span></div></div><div class="dash-chart">${hist.map(r=>{const rs=rowsFor({...state,activeFunding:funding},r,year),a=k=>rs.length?rs.reduce((n,x)=>n+Number(x.e[k]||0),0)/rs.length:0;return `<button class="dash-chart-column" data-open-report="${esc(r.id)}" aria-label="เปิด ${esc(weekLabel(r))} แผน ${a('plan').toFixed(2)}% ผลงาน ${a('actual').toFixed(2)}%"><span class="chart-value">${a('actual').toFixed(1)}%</span><span class="dash-chart-bars"><i style="height:${Math.min(100,Math.max(0,a('plan')))}%"></i><i style="height:${Math.min(100,Math.max(0,a('actual')))}%"></i></span><span class="chart-week-full">${esc(weekLabel(r))}</span><span class="chart-week-short">ส.${esc(weekLabel(r).replace(/^สัปดาห์ที่\s*/,''))}</span><small>${fmt(r.end||r.reference)}</small></button>`;}).join('')||'<p class="empty">ยังไม่มีข้อมูลความก้าวหน้า<br>สร้างสัปดาห์รายงานเพื่อเริ่มติดตามงาน</p>'}</div><div class="chart-note">ค่าเฉลี่ยรายสัญญาในแต่ละสัปดาห์ ไม่ถ่วงน้ำหนักวงเงิน</div></section><section class="card dash-status"><div class="card-header"><div><h2>สถานะโครงการ</h2><div class="sub">จากรายงานที่เลือก</div></div></div><div class="dash-completion"><strong>${rows.length?Math.round(done/rows.length*100):0}<small>%</small></strong><span>สัญญาที่แล้วเสร็จ</span></div><svg class="status-pie" viewBox="0 0 120 120" role="img" aria-label="สัดส่วนสถานะโครงการ">${[['ongoing',ongoing],['deliver',deliver],['pay',pay],['paid',paid]].map(([k,n],i,all)=>{const total=rows.length||1,offset=all.slice(0,i).reduce((sum,x)=>sum+x[1],0)/total*100;return `<circle class="${k}" cx="60" cy="60" r="45" fill="none" stroke-width="25" pathLength="100" stroke-dasharray="${n/total*100} ${100-n/total*100}" stroke-dashoffset="${-offset}" transform="rotate(-90 60 60)"><title>${k}: ${n} สัญญา</title></circle>`;}).join('')}</svg><div class="status-links">${[['ongoing','กำลังดำเนินการ',ongoing],['deliver','แล้วเสร็จ · รอส่งมอบ',deliver],['pay','รอเบิกจ่าย',pay],['paid','เบิกจ่ายแล้ว',paid]].map(([k,l,n])=>`<button data-dashboard-status="${k}"><span><i class="${k}"></i>${l}</span><b>${n}<span aria-hidden="true"> ${miniIcon('open')}</span></b></button>`).join('')}</div></section></div><section class="card dash-attention"><div class="card-header"><div><h2>งานที่ควรติดตาม <span class="attention-count">${attention.length}</span></h2><div class="sub">ผลงานต่ำกว่าแผน หรือยังไม่แล้วเสร็จและเลยกำหนดสัญญา ณ วันนี้</div></div><button class="text-link" data-action="alerts">ดูทั้งหมด ${miniIcon('open')}</button></div>${attention.slice(0,3).map(({p,e})=>`<button class="attention-row" data-edit="${esc(p.id)}"><span class="attention-contract">${esc(p.contract)}</span><span class="attention-name">${esc(p.title)}<small>${expired(p)?'เลยกำหนดสัญญา · ':''}สิ้นสุด ${fmt(p.end)}</small></span><span class="attention-progress"><strong>${Number(e.actual).toFixed(2)}%</strong><small>แผน ${Number(e.plan).toFixed(2)}%</small></span><span aria-hidden="true">${miniIcon('open')}</span></button>`).join('')||'<div class="dash-clear">✓ ไม่พบงานที่ต้องติดตามตามเงื่อนไขนี้ในรายงานที่เลือก</div>'}</section>${expiredContractsPanel()}${projectTable(rows,false,true)}</div>`;
}
let expiredPage=1;function expiredContractsPanel(){const rows=registryVisibleRecords().filter(r=>registryExpired(state,r)).sort((a,b)=>effectiveEnd(a).localeCompare(effectiveEnd(b))),max=Math.max(1,Math.ceil(rows.length/12));expiredPage=Math.min(expiredPage,max);return `<section class="card" id="expired-contracts"><h2>งานที่หมดอายุสัญญาและยังไม่แล้วเสร็จ <span class="pill warn">${rows.length}</span></h2><div class="table-scroll"><table data-selection-key="expired:${funding}:${year}" data-selection-ids="${esc(JSON.stringify(rows.map(x=>x.id)))}"><thead><tr><th>เลขสัญญา</th><th>ชื่องาน</th><th>วันสิ้นสุด</th><th>เกินกำหนด (วัน)</th><th></th></tr></thead><tbody>${rows.slice((expiredPage-1)*12,expiredPage*12).map(r=>`<tr data-select-id="${r.id}"><td>${esc(r.contract)}</td><td>${esc(r.title)}</td><td>${fmt(effectiveEnd(r))}</td><td>${days(today(),effectiveEnd(r))}</td><td><button class="btn" data-registry-view="${r.id}">ดูรายละเอียด</button></td></tr>`).join('')||'<tr><td colspan="5">ไม่มีสัญญาที่หมดอายุในกลุ่มงบและปีนี้</td></tr>'}</tbody></table></div><div class="table-foot"><span>หน้า ${expiredPage} / ${max}</span><button class="btn" data-expired-page="${expiredPage-1}" ${expiredPage===1?'disabled':''}>ก่อนหน้า</button><button class="btn" data-expired-page="${expiredPage+1}" ${expiredPage===max?'disabled':''}>ถัดไป</button></div></section>`;}
function projectTable(rows,weekly=false,dash=false){const counts={all:rows.length,ongoing:rows.filter(x=>!complete(x.e)).length,deliver:rows.filter(x=>statusKey(x.e)==='deliver').length,pay:rows.filter(x=>statusKey(x.e)==='pay').length,paid:rows.filter(x=>x.e.payment==='เบิกจ่ายแล้ว').length};const filtered=reportRowsMatching(rows).slice().sort(weekly&&weeklySort.key?(a,b)=>compareData(a,b,weeklySort.key,weeklySort.dir):sortRows);const size=weekly?100:dash?5:12;const max=Math.max(1,Math.ceil(filtered.length/size));page=Math.min(page,max);const slice=filtered.slice((page-1)*size,page*size);return `<div class="card table-card"><div class="table-top"><div><h2>${weekly?'บันทึกผลงานประจำสัปดาห์':'ทะเบียนโครงการ'}</h2><div class="sub">${weekly?'ทบทวนทุกโครงการก่อนยืนยันและปิดรายงาน':'ข้อมูลสัญญาและความก้าวหน้าในสัปดาห์รายงานที่เลือก'}</div></div>${weekly?`<span class="review-count">ยืนยันแล้ว ${rows.filter(x=>x.e.confirmed).length}/${rows.length}</span>`:`<button class="text-link" data-view="projects">ดูทะเบียนทั้งหมด ↗</button>`}</div>${weekly?'':`<div class="tabs">${[['all','ทั้งหมด'],['ongoing','กำลังดำเนินการ'],['deliver','รอส่งมอบงาน'],['pay','รอเบิกจ่าย'],['paid','เบิกจ่ายแล้ว']].map(([v,t])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${t}<b>${counts[v]}</b></button>`).join('')}</div>`}<div class="filters"><input id="search" class="search" placeholder="⌕ ค้นหาชื่องาน เลขสัญญา หรือผู้รับจ้าง" value="${esc(query)}"><select id="category-filter"><option value="">ทุกประเภทงาน</option>${state.workTypes.filter(c=>!c.deletedAt).map(c=>`<option value="${c.id}" ${category===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><span class="sub" style="margin-left:auto">${filtered.length} รายการ</span></div><div class="table-scroll"><table data-selection-key="weekly:${selected}" data-selection-ids="${esc(JSON.stringify(filtered.map(x=>x.p.id)))}"><thead><tr>${weekly?sortHead('เลขสัญญา','p.contract','weekly',weeklySort)+sortHead('งาน / ผู้รับจ้าง','p.title','weekly',weeklySort):'<th>สัญญา / รหัส</th><th>โครงการ / ผู้รับจ้าง</th>'}${weekly?[['แผนสะสม %','e.plan'],['ผลงานสัปดาห์ %','e.weekly'],['ผลงานสะสม %','e.actual'],['หมายเหตุ','e.note'],['การเบิกจ่าย','e.payment']].map(([l,k])=>sortHead(l,k,'weekly',weeklySort)).join('')+'<th>ยืนยัน</th>':'<th>ระยะเวลาสัญญา</th><th>ความก้าวหน้า</th><th>สถานะ</th><th>จัดการ</th>'}</tr></thead><tbody>${slice.map(({p,e})=>`<tr class="${statusKey(e)==='paid'?'paid':statusKey(e)==='deliver'?'waiting-delivery':statusKey(e)==='pay'?'waiting-payment':''}" data-id="${p.id}"><td><div class="code">${esc(p.contract)}</div></td><td><button class="name contract-open" data-edit="${p.id}" title="ดูข้อมูลสัญญา">${esc(p.title)}${weekly?`<button class="text-link" data-report-name="${p.id}">แก้ชื่องานในรายงาน</button><button class="text-link" data-report-name="${p.id}" data-name-kind="supervisor">แก้ชื่อผู้ควบคุมในรายงาน</button>`:''}</button><div class="sub">${esc(p.contractor)}</div></td>${weekly?['plan','weekly','actual'].map(k=>`<td><input aria-label="${k} ${esc(p.contract)}" data-entry="${k}" class="weekly-input" type="number" min="0" max="100" step="0.01" value="${e[k]}" ${report().locked?'disabled':''}>${report().locked?`<button class="text-link" data-amend-entry="${p.id}">แก้ไข</button>`:''}</td>`).join('')+`<td><input aria-label="หมายเหตุ ${esc(p.contract)}" data-entry="note" class="weekly-note" value="${esc(e.note)}" ${report().locked?'disabled':''}></td><td><select aria-label="การเบิกจ่าย ${esc(p.contract)}" data-entry="payment" class="weekly-select" ${report().locked?'disabled':''}>${['รอส่งมอบงาน','รอเบิกจ่าย','เบิกจ่ายแล้ว'].map(s=>`<option ${s===e.payment?'selected':''}>${s}</option>`).join('')}</select><button class="text-link" data-contract-dates="${p.id}">${e.paymentDate||e.deliveryDate||e.acceptanceDate?'แก้ไขวันที่':'บันทึกวันที่'}</button></td><td><input aria-label="ยืนยัน ${esc(p.contract)}" data-entry="confirmed" type="checkbox" ${e.confirmed?'checked':''} ${report().locked?'disabled':''}>${report().locked?`<button class="text-link" data-amend-entry="${p.id}">แก้ไข</button>`:''}</td>`:`<td>${fmt(p.end)}<div class="sub">${effectiveDays(p)} วัน · ดำเนินการ ${report().reference?elapsed(p,e,report().reference):'ไม่ระบุ'} วัน</div></td><td><div class="progress"><div class="track"><span style="width:${e.actual}%"></span></div>${Number(e.actual).toFixed(2)}%</div><div class="sub">แผน ${Number(e.plan).toFixed(2)}%</div></td><td><span class="pill ${complete(e)?'':expired(p)?'red':'warn'}">${complete(e)?'แล้วเสร็จ':'อยู่ระหว่างดำเนินการ'}</span><div class="sub">${e.payment}</div></td><td><button class="edit" data-edit="${p.id}">รายละเอียด ↗</button></td>`}</tr>`).join('')||'<tr><td colspan="9" class="empty">ไม่พบโครงการในเงื่อนไขที่เลือก</td></tr>'}</tbody></table></div><div class="table-foot"><span>แสดง ${filtered.length?((page-1)*size+1):0}–${Math.min(page*size,filtered.length)} จาก ${filtered.length} รายการ</span><div class="actions"><button data-page="${page-1}" ${page<=1?'disabled':''}>←</button><span>หน้า ${page} / ${max}</span><button data-page="${page+1}" ${page>=max?'disabled':''}>→</button></div></div></div>`;}
function weekly(){if(report().id==='EMPTY'||(report().funding||'DOH')!==funding||(report().year&&report().year!==year))return header('อัปเดตรายสัปดาห์','ยังไม่มีรายงานของกลุ่มงบและปีที่เลือก',`<button class="btn" data-action="restore">↑ นำเข้า JSON</button><button class="btn primary" data-action="new-report">＋ สร้างสัปดาห์รายงาน</button>`)+periodBar()+'<div class="notice">กด <strong>↑ นำเข้า JSON</strong> เพื่อสร้างสัปดาห์รายงานและแยกกลุ่มงบ (กรมทางหลวง / งบจังหวัด) ตามช่วงสัปดาห์ที่รายงานให้อัตโนมัติ หรือเพิ่มสัญญาในทะเบียนสัญญาแล้วกดสร้างสัปดาห์รายงาน</div>';return header('อัปเดตรายสัปดาห์','วันอ้างอิงคำนวณ: '+fmt(report().reference)+' · สัปดาห์อังคาร–จันทร์',`<button class="btn" data-action="restore">↑ นำเข้า JSON</button><button class="btn" data-action="preview">ดูตัวอย่างรายงาน</button>${report().locked?'<button class="btn" data-action="amend-report">แก้ไขรายงาน</button><button class="btn primary" data-action="new-report">＋ สร้างสัปดาห์ถัดไป</button>':'<button class="btn" data-action="carry">ดึงค่าสัปดาห์ก่อน</button><button class="btn" data-action="confirm-unchanged">ยืนยันรายการที่ไม่เปลี่ยน</button><button class="btn primary" data-action="lock">✓ ตรวจสอบและปิดรายงาน</button>'}`)+periodBar()+(report().locked?'<div class="notice">รายงานนี้เก็บเป็นประวัติแล้ว สามารถดูและส่งออกได้ กดแก้ไขรายงานเพื่อปรับข้อมูลย้อนหลังได้ ระบบเก็บประวัติให้อัตโนมัติ</div>':'')+(!report().locked?`<div class="week-management"><button class="btn" data-action="edit-week">${miniIcon('edit')} แก้ไขช่วงสัปดาห์</button><button class="btn danger" data-action="cancel-week">${miniIcon('delete')} ยกเลิกสัปดาห์</button></div>`:'')+(!report().locked&&missingPaymentDates(report()).length?`<div class="notice" role="status">ข้อมูลเดิมมีสถานะเบิกจ่ายแล้วแต่ยังไม่ระบุวันที่ ${missingPaymentDates(report()).length} สัญญา สร้างและแก้ไขฉบับร่างได้ กรุณากดบันทึกวันที่ให้ครบก่อนปิดรายงาน <button class="text-link" data-filter="paid">ดูสัญญาที่เบิกจ่ายแล้ว</button></div>`:'')+weeklySummary(activeRows())+projectTable(activeRows(),true);}
function projects(){const rows=registryVisibleRecords();return header('ทะเบียนสัญญา','ข้อมูลสัญญากลางสำหรับรายงานของแต่ละกลุ่มงบและปีงบประมาณ',`<details class="file-menu"><summary class="btn">นำเข้า / ส่งออก</summary><div class="file-menu-items"><button class="btn" data-action="restore">↑ นำเข้า JSON</button><button class="btn" data-action="convert-g3">นำเข้าจากแพลนเน็ต ก-3</button><button class="btn" data-action="import-personnel">นำเข้าคณะกรรมการ / ผู้ควบคุม ก-4</button><button class="btn" data-action="import-registry-csv">นำเข้า Excel</button><button class="btn" data-action="export-registry-xlsx">ส่งออก Excel</button><button class="btn" data-action="export-personnel-xlsx">ส่งออกบุคลากร ก-4</button><button class="btn" data-action="personnel-template">แม่แบบบุคลากร ก-4</button><button class="btn" data-action="registry-template">แม่แบบ Excel</button><button class="btn" data-action="export-registry-csv">CSV เดิม</button></div></details><button class="btn primary" data-action="new-project">＋ เพิ่มสัญญา</button>`)+periodBar(false)+importResultCard(state,'contractRegistry')+registrySummary(rows)+registryTable(rows);}

function reports(){const list=state.reports.filter(r=>reportMatchesScope(state,r,year,funding)&&(!archiveQuery||(weekLabel(r)+' '+fmt(r.start)+' '+fmt(r.end)).includes(archiveQuery))).sort((a,b)=>(b.end||'').localeCompare(a.end||''));const max=Math.max(1,Math.ceil(list.length/10));archivePage=Math.min(max,archivePage);const shown=list.slice((archivePage-1)*10,archivePage*10);return header('คลังรายงาน','รายงานประจำสัปดาห์ เรียงจากล่าสุดก่อน',`<button class="btn" data-action="restore">↑ นำเข้า JSON</button><button class="btn primary" data-action="new-report">＋ สร้างสัปดาห์รายงาน</button>`)+archiveFilters()+`<div class="card"><div class="filters"><input id="archive-search" class="search" aria-label="ค้นหารายงาน" placeholder="ค้นหาสัปดาห์หรือช่วงวันที่" value="${esc(archiveQuery)}">${archiveQuery?'<button class="btn" id="clear-archive" aria-label="ล้างคำค้น">ล้าง</button>':''}<span class="sub">${list.length} รายงาน</span></div><div class="table-scroll"><table class="archive-table" data-selection-key="reports:${funding}:${year}" data-selection-ids="${esc(JSON.stringify(list.map(x=>x.id)))}"><thead><tr><th>สัปดาห์</th><th>ช่วงวันที่</th><th>จำนวนงาน</th><th>สถานะ</th><th></th></tr></thead><tbody>${shown.map(r=>`<tr data-select-id="${r.id}"><td><strong>${esc(weekLabel(r))}</strong></td><td>${r.end?fmt(r.start)+' – '+fmt(r.end):'ต้นฉบับไม่ระบุช่วงวันที่'}${r.modifiedAt?`<button class="amended-indicator" data-amend-info="${r.id}" aria-label="ดูวันที่แก้ไขล่าสุด">✎ แก้ไขแล้ว</button>`:''}</td><td>${r._entryCount??rowsFor({...state,activeFunding:funding},r,year).length}<span class="mobile-unit"> งาน</span></td><td><span class="pill ${r.locked?'':'warn'}">${r.locked?'เก็บรายงานแล้ว':'ฉบับร่าง'}</span></td><td><button class="btn" data-open-report="${r.id}">เปิดรายงาน</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">ไม่พบรายงาน ลองเปลี่ยนปี กลุ่มงบ หรือคำค้น</td></tr>'}</tbody></table></div><div class="table-foot"><span>หน้า ${archivePage} / ${max}</span><div class="actions"><button class="btn" data-archive-page="${archivePage-1}" ${archivePage===1?'disabled':''}>ก่อนหน้า</button><button class="btn" data-archive-page="${archivePage+1}" ${archivePage===max?'disabled':''}>ถัดไป</button></div></div></div>`;}
function archiveFilters(){return `<div class="period-bar"><div class="period-control">${selectField('กลุ่มงบ','archiveFunding',state.fundingSources.map(x=>({value:x.id,label:x.name})),funding)}${selectField('ปีงบประมาณ','archiveYear',state.years,year)}</div></div>`;}
function bindArchive(){const f=$('[name=archiveFunding]'),y=$('[name=archiveYear]');if(f){f.value=funding;f.onchange=async()=>{funding=f.value;archivePage=1;try{await ensureScope();}catch(e){toast(e.message,true);}render();};}if(y){y.value=String(year);y.onchange=async()=>{year=+y.value;archivePage=1;try{await ensureScope();}catch(e){toast(e.message,true);}render();};}$('#archive-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;archiveQuery=e.target.value;archivePage=1;render();$('#archive-search').focus();$('#archive-search').setSelectionRange(pos,pos);});$('#clear-archive')?.addEventListener('click',()=>{archiveQuery='';archivePage=1;render();$('#archive-search').focus();});$$('[data-archive-page]').forEach(b=>b.onclick=()=>{archivePage=+b.dataset.archivePage;render();});$$('[data-amend-info]').forEach(b=>b.onclick=()=>{const r=state.reports.find(r=>r.id===b.dataset.amendInfo);modal('แก้ไขรายงานแล้ว',`<p>แก้ไขล่าสุด ${esc(new Date(r.modifiedAt).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'}))}</p><p class="sub">แก้ไขแล้ว ${r.amendedVersion||1} ครั้ง</p>`);});}

let importHistoryPage=1;
function audit(){return header('ประวัติการเปลี่ยนแปลง','ประวัติการดำเนินการและค่าเดิม / ค่าใหม่ที่เปลี่ยนแปลง','<button class="btn" data-action="export-import-history">↓ ส่งออกประวัติ CSV</button>')+`<div class="card">${importHistoryHTML(state.importHistory||[],importHistoryPage)}</div><div class="card">${state.audit.length?state.audit.map(a=>`<div class="audit-item"><span>${esc(a.action)}</span><span class="sub">${new Date(a.at).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})}</span></div>`).join(''):'<div class="empty">ยังไม่มีการแก้ไขหลังนำเข้าข้อมูล</div>'}</div>`;}
let qualityPage=1;
let qualityMode='open';
function quality(){const all=qualityIssues(state,year,funding),reviewed=state.settings.qualityReviews||{},issues=all.filter(x=>qualityMode==='reviewed'?!!reviewed[qualityReviewKey(x)]:!reviewed[qualityReviewKey(x)]),pages=Math.max(1,Math.ceil(issues.length/25));qualityPage=Math.min(qualityPage,pages);return header('ตรวจข้อมูล','ตรวจแล้วสามารถซ่อนจากรายการค้างตรวจ และเปิดดูย้อนหลังได้','')+periodBar(false)+`<div class="card"><div class="tabs"><button data-quality-mode="open" class="${qualityMode==='open'?'active':''}">รอตรวจ ${all.filter(x=>!reviewed[qualityReviewKey(x)]).length}</button><button data-quality-mode="reviewed" class="${qualityMode==='reviewed'?'active':''}">ตรวจแล้ว ${all.filter(x=>reviewed[qualityReviewKey(x)]).length}</button></div><div class="table-scroll"><table data-selection-key="quality" data-selection-ids="${esc(JSON.stringify(issues.map(qualityReviewKey)))}"><thead><tr><th>ประเด็น</th><th>รายการ</th><th>ดำเนินการ</th></tr></thead><tbody>${issues.slice((qualityPage-1)*25,qualityPage*25).map(x=>`<tr data-select-id="${esc(qualityReviewKey(x))}"><td>${esc(x.type)}</td><td>${esc(x.label)}</td><td>${x.reportId?`<button class="btn" data-open-report="${esc(x.reportId)}">เปิดรายงาน</button>`:`<button class="btn" data-registry-edit="${esc(x.registryId)}">ตรวจสัญญา</button>`}<button class="btn" data-quality-review="${esc(qualityReviewKey(x))}">${qualityMode==='reviewed'?'นำกลับไปรอตรวจ':'ตรวจแล้ว / ผ่าน'}</button></td></tr>`).join('')||'<tr><td colspan="3">ไม่มีรายการในหมวดนี้</td></tr>'}</tbody></table></div><div class="table-foot"><span>หน้า ${qualityPage} / ${pages}</span><button class="btn" data-quality-page="${qualityPage-1}" ${qualityPage===1?'disabled':''}>ก่อนหน้า</button><button class="btn" data-quality-page="${qualityPage+1}" ${qualityPage===pages?'disabled':''}>ถัดไป</button></div></div>`;}
function settings(){return header('ตั้งค่าระบบ','ตั้งค่ารายงาน สำรองข้อมูล และเชื่อมต่อ Supabase')+`<div class="grid2"><div class="card settings-section"><h2>รูปแบบรายงาน</h2><form id="settings-form"><div class="form-grid" style="margin-top:20px">${field('หน่วยงาน','organization',state.settings.organization,'text','required')}${field('ชื่อระบบ','systemName',state.settings.systemName,'text','required')}<label class="field">โลโก้ PNG (ไม่เกิน 500 KB)<input id="logo-file" type="file" accept="image/png"><span class="hint">ใช้ทั้งหน้าเว็บและไอคอนแท็บ</span></label>${state.settings.logo?`<div class="field"><img src="${state.settings.logo}" alt="โลโก้ปัจจุบัน" style="width:64px;height:64px;object-fit:contain"><label><input type="checkbox" name="removeLogo"> ลบโลโก้</label></div>`:''}${field('ชื่อรายงานกรมทางหลวง','titleDOH',state.settings.reportTitles.DOH,'text','required')}${field('ชื่อรายงานงบจังหวัด','titleProvince',state.settings.reportTitles.PROVINCE,'text','required')}<div class="field">สัปดาห์รายงาน<input value="อังคาร–จันทร์ · ใช้จันทร์ท้ายรอบ" disabled></div></div><div class="dialog-actions"><button class="btn primary" type="submit">บันทึกการตั้งค่า</button></div></form></div><div class="card"><h2>สำรองและย้ายข้อมูล</h2><p class="sub">สำรองทะเบียนสัญญา รายงานทุกสัปดาห์ และประวัติ เป็น JSON</p><div class="actions"><button class="btn" data-action="backup">↓ สำรองข้อมูลทั้งหมด</button><button class="btn primary" data-action="restore">↑ นำเข้าข้อมูล JSON</button></div><p class="hint">ข้อมูลปัจจุบัน ${state.projects.length} สัญญา และ ${state.reports.filter(r=>r.id!=='EMPTY').length} รายงาน • ไฟล์สำรองมีข้อมูลจริง ควรเก็บในพื้นที่ที่จำกัดสิทธิ์</p></div></div>`;}
let lastNormalizedState;function render(){const focused=document.activeElement?.matches('[data-entry]')?{id:document.activeElement.closest('tr').dataset.id,key:document.activeElement.dataset.entry}:null;activeRowsCache=undefined;if(lastNormalizedState!==state){normalizeState(state);lastNormalizedState=state;}try{localStorage.setItem('pn-weekly-filters',JSON.stringify({year,funding}));}catch{}applyBrand();if(!state.years.includes(year))year=state.years[0];if(report().id==='EMPTY'||(!report().year&&!reportMatchesScope(state,report(),year,funding))||(report().year&&report().year!==year)||((report().funding||'DOH')!==funding))selected=state.reports.find(r=>reportMatchesScope(state,r,year,funding))?.id;const r=report();$('#crumb').textContent=names[view];$('#pending-count').textContent=activeRows().filter(x=>!complete(x.e)).length;$('#storage-status').innerHTML=cloudMode?'เชื่อมต่อฐานข้อมูล<small>พื้นที่ข้อมูลเดียว · ไม่ต้องเข้าสู่ระบบ</small>':'จัดเก็บบนอุปกรณ์นี้<small>สำรองข้อมูลได้จากเมนูตั้งค่า</small>';$('#mode-tag').textContent=cloudMode?'ฐานข้อมูล · เชื่อมต่อแล้ว':'ข้อมูลบนอุปกรณ์นี้';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#app').innerHTML=(storageWarning?'<div class="notice" role="alert">บันทึกสำรองบนอุปกรณ์ไม่ได้ ข้อมูลชั่วคราวอาจหายเมื่อปิดหน้า '+(cloudMode?'ข้อมูลที่ส่งสำเร็จยังอยู่บนฐานข้อมูล':'กรุณาสำรอง JSON ก่อนปิดหน้า')+'</div>':'')+`<button class="sync-status" id="sync-status" type="button" aria-live="polite">สถานะการส่งข้อมูล</button>`+({dashboard,weekly,projects,reports,catalog,audit,settings,quality}[view])();$('#sync-status').onclick=outboxDialog;bind();mountSelections();restoreEdits();if(focused){const input=$$('[data-entry]').find(x=>x.closest('tr').dataset.id===focused.id&&x.dataset.entry===focused.key);input?.focus({preventScroll:true});}}
function confirmAction(title,message,fn){modal(title,`<p class="sub">${esc(message)}</p><form>${buttons(title.includes('ลบ')?'ยืนยันลบ':'ยืนยัน')}</form>`,fn);}
function editWeek(){const r=report();modal('แก้ไขช่วงสัปดาห์รายงาน',`<form><div class="form-grid">${field('วันเริ่มรอบ (อังคาร)','start',r.start,'date','required')}${field('วันสิ้นสุด (จันทร์)','end',r.end,'date','required')}</div><p class="hint">แก้ได้เฉพาะฉบับร่างล่าสุด เปอร์เซ็นต์สะสมคงเดิมและตรวจยืนยันใหม่</p>${buttons('บันทึกช่วงวันที่')}</form>`,f=>mutate('แก้ไขสัปดาห์รายงาน',s=>changeDraftWeek(s,r.id,{start:f.get('start'),end:f.get('end')})));$('#modal [name=start]').oninput=e=>{if(/^\d{4}-\d{2}-\d{2}$/.test(e.target.value))$('#modal [name=end]').value=addDays(e.target.value,6);};}
function cancelWeek(){const r=report();if(r.locked)return toast('ยกเลิกได้เฉพาะฉบับร่าง รายงานที่ปิดแล้วเก็บประวัติไว้',true);confirmAction('ยืนยันยกเลิกสัปดาห์รายงาน','ลบฉบับร่างนี้และผลงานที่กรอกในสัปดาห์นี้ รายงานเดิมอื่นๆคงอยู่',async()=>{await mutate('ยกเลิกสัปดาห์รายงาน',s=>{if(s.reports.some(x=>x.id!==r.id&&x.end&&x.end>r.end&&x.year===r.year&&(x.funding||'DOH')===funding))throw Error('มีสัปดาห์ถัดไปแล้ว ยกเลิกได้เฉพาะฉบับร่างล่าสุด');s.reports=s.reports.filter(x=>x.id!==r.id);if(!s.reports.length)s.reports.push(clone(BOOTSTRAP.reports[0]));});selected=state.reports.find(x=>x.end)?.id;render();});}
function newReport(){const last=state.reports.filter(r=>r.end&&reportMatchesScope(state,r,year,funding)).sort((a,b)=>b.end.localeCompare(a.end))[0];const range=last?{start:addDays(last.start,7),end:addDays(last.end,7)}:rangeFor(today());modal('สร้างสัปดาห์รายงาน',`<p class="sub">ระบบดึงข้อมูลล่าสุดที่เกิดก่อนสัปดาห์นี้ให้ทุกสัญญาในปี ${year}</p><form><div class="form-grid">${field('วันเริ่มรอบ (อังคาร)','start',range.start,'date','required')}${field('วันสิ้นสุด / วันอ้างอิง (จันทร์)','end',range.end,'date','required')}</div><p class="hint">ผลงานรายสัปดาห์เริ่มที่ 0 และรอยืนยันทุกแถว</p>${buttons('สร้างและเปิดสัปดาห์รายงาน')}</form>`,async f=>{if(cloudMode&&last&&f.get('start')<=last.end)state=await cloud.loadFullCloud();let id;await mutate('สร้างสัปดาห์รายงาน',s=>{const r=createReport(s,{start:f.get('start'),end:f.get('end'),reference:f.get('end')},year,funding);id=r.id;s.reports.unshift(r);},undefined,()=>{selected=id;view='weekly';filter='all';page=1;});});$('#modal [name=start]').oninput=e=>{if(/^\d{4}-\d{2}-\d{2}$/.test(e.target.value))$('#modal [name=end]').value=addDays(e.target.value,6);};}
function projectDialog(id){const r=findRegistryRecord(id);if(r)registryEditDialog(r.id);}
function preview(){const r=selectedReport();if(!Object.keys(r.entries).length)return toast('กรุณาเลือกรายการที่จะส่งออก',true);if((r.funding||'DOH')!==funding||(r.year&&r.year!==year))return toast('ยังไม่มีรายงานสำหรับกลุ่มงบและปีที่เลือก',true);if(!r.start||!r.end||!r.reference)return toast('รายงานต้นฉบับนี้ยังไม่มีช่วงวันที่ที่ตรวจสอบแล้ว กรุณาสร้างสัปดาห์ใหม่',true);modal('ตัวอย่างรายงานผู้บริหาร',`<div class="actions" style="margin-bottom:15px">${r.locked?'<button class="btn" id="amend-preview">แก้ไขรายงาน</button>':''}<button class="btn primary" id="print-report">↓ PDF / พิมพ์</button><button class="btn" id="xlsx-report">↓ Excel .xlsx</button><button class="btn" id="jpg-report">↓ รูปภาพ JPG</button></div>${!r.locked?'<div class="notice">ฉบับร่าง — ยังไม่ปิดรายงาน โปรดตรวจสอบก่อนนำเสนอ</div>':''}<div class="report-preview">${reportHTML({...state,activeFunding:funding},r,year)}</div>`);$('#modal').style.width='1150px';$('#amend-preview')?.addEventListener('click',()=>{$('#modal').close();amendDialog();});$('#print-report').onclick=()=>{void logActivity('เปิดพิมพ์รายงาน PDF',[],{reportId:r.id,count:Object.keys(r.entries).length});let el=$('.print-report');if(!el){el=document.createElement('div');el.className='print-report';document.body.append(el);}el.innerHTML=reportHTML({...state,activeFunding:funding},r,year);$('#modal').close();window.print();};$('#jpg-report').onclick=async()=>{void logActivity('ส่งออกรายงานรูปภาพ',[],{reportId:r.id,count:Object.keys(r.entries).length});try{const n=await exportImages({...state,activeFunding:funding},r,year);toast('สร้างภาพแล้ว '+n+' หน้า หากดาวน์โหลดไม่ครบให้อนุญาตการดาวน์โหลดหลายไฟล์');}catch(e){toast(e.message,true);}};$('#xlsx-report').onclick=()=>{void logActivity('ส่งออกรายงาน Excel',[],{reportId:r.id,count:Object.keys(r.entries).length});download(xlsxBlob({...state,activeFunding:funding},r,year),'PN-weekly-'+year+'-'+funding+'-'+r.end+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');};}
function alerts(){const rows=activeRows();modal('รายการที่ควรตรวจสอบ',`<div class="notice">อายุสัญญาเทียบวันปัจจุบัน ${fmt(today())} ส่วนจำนวนวันดำเนินการเทียบจันทร์ท้ายสัปดาห์รายงาน</div>${rows.filter(x=>!complete(x.e)&&(expired(x.p)||x.e.plan>x.e.actual)).map(({p,e})=>`<div class="audit-item"><div><b>${esc(p.contract)} · ${esc(p.title)}</b><div class="sub">${expired(p)?'หมดอายุสัญญา '+fmt(p.end):''} · ผลงานต่ำกว่าแผน ${(e.plan-e.actual).toFixed(2)}%</div></div><button class="text-link" data-alert-edit="${p.id}">ดูสัญญา</button></div>`).join('')||'<div class="empty">ไม่พบรายการที่ต้องติดตาม</div>'}<h3 style="margin-top:20px">ข้อมูลนำเข้าที่ต้องทบทวน</h3>${(state.issues||[]).filter(i=>!i['กลุ่มงบ']||i['กลุ่มงบ']===funding).map(i=>`<div class="audit-item"><div><b>${esc(i.project||[i['กลุ่มงบ']?fundingName(state,i['กลุ่มงบ']):'',i['แผ่นงาน'],i['แถว']?'แถว '+i['แถว']:''].filter(Boolean).join(' · '))}</b><div class="sub">${esc(i.message||i['ประเด็น']||'')}<br>${esc(i.raw||i['รายละเอียด']||'')}</div></div></div>`).join('')}<p class="sub">หัวรายงานเดิมระบุ พรบ.69 แต่เลขสัญญาเป็นปี 2568 • อ่านช่วงวันที่ได้ 56 จาก 57 รายงาน ส่วนรอบที่ 46 ต้องตรวจหัววันที่ในต้นฉบับ • หนังสือขยายสัญญาที่นำเข้ายังไม่มีเลขอ้างอิง</p>`);$$('[data-alert-edit]').forEach(b=>b.onclick=()=>{$('#modal').close();projectDialog(b.dataset.alertEdit);});}
