function bind(){bindSettings();$$('[data-dashboard-status]').forEach(b=>b.onclick=async()=>{try{if(b.dataset.dashboardStatus==='expired'){$('#expired-contracts')?.scrollIntoView({block:'start'});return;}await ensureScope();view='weekly';filter=b.dataset.dashboardStatus;page=1;query='';category='';render();window.scrollTo({top:0,behavior:'smooth'});}catch(e){toast(e.message,true);}});$('#discard-edits')?.addEventListener('click',()=>confirmAction('ยกเลิกค่าที่ค้างบันทึก','ค่าที่ค้างบนอุปกรณ์จะถูกล้าง กรุณาตรวจให้แน่ใจว่าไม่ต้องการส่งค่าเหล่านี้',()=>{editDrafts.clear();persistEdits();render();}));$$('[data-import-history-page]').forEach(b=>b.onclick=()=>{importHistoryPage=+b.dataset.importHistoryPage;render();});bindRegistry();bindArchive();$$('[data-amend-entry]').forEach(b=>b.onclick=()=>amendDialog(b.dataset.amendEntry));if($('#year'))$('#year').value=String(year);if($('#funding-select'))$('#funding-select').value=funding;bindCatalog();$$('[data-view]').forEach(b=>b.onclick=async()=>{view=b.dataset.view;filter='all';page=1;query='';category='';budgetFilter='';$('.sidebar').classList.remove('open');try{await ensureScope();if(view==='audit'&&cloudMode&&state.importHistory===undefined){const history=await cloud.loadHistoryCloud();if(history.revision!==state.revision)throw Error('ข้อมูลเปลี่ยนแปลงแล้ว กรุณาโหลดข้อมูลล่าสุดก่อนเปิดประวัติ');state.importHistory=history.importHistory||[];delete state.importHistoryDeferred;await cacheWorkspace(state);}await ensureFirstWeekly();render();}catch(e){toast(e.message,true);render();}});$$('[data-action]').forEach(b=>b.onclick=async()=>{try{await actions[b.dataset.action]?.();if((b.dataset.action.startsWith('export-')&&b.dataset.action!=='export-registry-xlsx')||b.dataset.action==='registry-template')void logActivity('ส่งออก '+b.textContent.trim(),[],{funding,year});}catch(e){toast(e.message,true);}});$('#funding-select')?.addEventListener('change',async e=>{funding=e.target.value;budgetFilter='';page=1;try{await ensureScope();await ensureFirstWeekly();render();}catch(err){toast(err.message,true);render();}});$('#year')?.addEventListener('change',async e=>{year=+e.target.value;budgetFilter='';page=1;try{await ensureScope();await ensureFirstWeekly();render();}catch(err){toast(err.message,true);render();}});$('#report-select')?.addEventListener('change',async e=>{selected=e.target.value;page=1;try{await ensureScope(selected);render();}catch(err){toast(err.message,true);}});$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;page=1;render();});$('#search')?.addEventListener('input',e=>{if(e.isComposing)return;clearTimeout(searchTimer);const value=e.target.value,pos=e.target.selectionStart;searchTimer=setTimeout(()=>{query=value;page=1;render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);},120);});$('#category-filter')?.addEventListener('change',e=>{category=e.target.value;page=1;render();});$$('[data-page]').forEach(b=>b.onclick=()=>{page=+b.dataset.page;render();});$$('[data-edit]').forEach(b=>b.onclick=()=>projectDialog(b.dataset.edit));$$('[data-open-report]').forEach(b=>b.onclick=async()=>{const r=state.reports.find(x=>x.id===b.dataset.openReport);funding=r.funding||'DOH';year=r.year||year;try{await ensureScope(b.dataset.openReport);selected=b.dataset.openReport;view='weekly';filter='all';page=1;render();}catch(e){toast(e.message,true);render();}});$$('[data-entry]').forEach(input=>{const reportId=selected,id=input.closest('tr').dataset.id,k=input.dataset.entry,key=reportId+'|'+id+'|'+k;input.oninput=()=>{editDrafts.set(key,{reportId,id,k,value:input.type==='checkbox'?input.checked:input.value});persistEdits();updateSaveStatus();};input.onchange=()=>submitWeeklyEdit(reportId,id,k,input.type==='checkbox'?input.checked:['plan','weekly','actual'].includes(k)?+input.value:input.value);});$$('[data-quality-page]').forEach(b=>b.onclick=()=>{qualityPage=+b.dataset.qualityPage;render();});$('#retry-edits')?.addEventListener('click',async()=>{const failed=[...editDrafts.values()].filter(x=>x.error),first=failed[0];if(!first)return;const r=state.reports.find(x=>x.id===first.reportId);funding=r?.funding||funding;year=r?.year||year;try{await ensureScope(first.reportId);}catch(e){toast(e.message,true);render();return;}selected=first.reportId;view='weekly';filter='all';render();for(const x of failed.filter(x=>x.reportId===first.reportId))submitWeeklyEdit(x.reportId,x.id,x.k,['plan','weekly','actual'].includes(x.k)?+x.value:x.value);});}
function updateWeeklyRowDOM(id){const r=report(),e=r.entries[id];if(filter!=='all'&&statusKey(e)!==filter){render();return;}const row=[...document.querySelectorAll('tr[data-id]')].find(x=>x.dataset.id===id);if(!row){render();return;}row.className=statusKey(e)==='paid'?'paid':statusKey(e)==='deliver'?'waiting-delivery':statusKey(e)==='pay'?'waiting-payment':'';row.querySelectorAll('[data-entry]').forEach(input=>{const key=r.id+'|'+id+'|'+input.dataset.entry;if(document.activeElement===input||editDrafts.has(key))return;if(input.type==='checkbox')input.checked=!!e[input.dataset.entry];else input.value=e[input.dataset.entry]??'';});const allRows=rowsFor(state,r,year);const reviewed=document.querySelector('.review-count');if(reviewed)reviewed.textContent='ยืนยันแล้ว '+allRows.filter(x=>x.e.confirmed).length+'/'+allRows.length;const pending=document.querySelector('#pending-count');if(pending)pending.textContent=allRows.filter(x=>!x.e.confirmed).length||'';const summary=document.querySelector('.register-summary');if(summary){const template=document.createElement('template');template.innerHTML=weeklySummary(rowsFor(state,r,year));summary.replaceWith(template.content.firstElementChild);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;page=1;render();});}updateSaveStatus();restoreEdits();}
async function submitWeeklyEdit(reportId,id,k,value){const key=reportId+'|'+id+'|'+k,token=uid();editDrafts.set(key,{reportId,id,k,value,token});persistEdits();try{await mutate('อัปเดตผลงาน '+id,s=>{const r=s.reports.find(x=>x.id===reportId);if(r.locked)throw Error('รายงานถูกปิดแล้ว');const e=r.entries[id];e[k]=value;if(k==='payment'){if(value==='เบิกจ่ายแล้ว'){e.paymentDate||=report().reference||today();e.note=paymentNote(e);}else{if(e.note?.startsWith('เบิกจ่ายแล้ว วันที่ '))e.note='';e.paymentDate='';}}if(k==='paymentDate'){if(!value)throw Error('กรุณาเลือกวันที่เบิกจ่าย');e.note=paymentNote(e);}const prev=previousEntry(r,id);if(k==='weekly')e.actual=+(Number(prev?.actual||0)+value).toFixed(2);if(k==='actual')e.weekly=+(value-Number(prev?.actual||0)).toFixed(2);validateDates(e);if(k!=='confirmed')e.confirmed=false;if(['weekly','actual','confirmed','payment','paymentDate'].includes(k))validateEntry(e,prev||{actual:0});else validateEntry(e);if(['note','payment','paymentDate','deliveryDate','acceptanceDate'].includes(k))syncContractDates(s,id,e,(k==='payment'?['paymentDate','payment','note']:[k]).filter(key=>!['note','payment'].includes(key)||!s.reports.some(later=>later.end>r.end&&later.entries?.[id])));},undefined,undefined,{reportId,id});if(editDrafts.get(key)?.token===token)editDrafts.delete(key);persistEdits();restoreEdits();}catch(e){if(editDrafts.get(key)?.token===token)editDrafts.get(key).error=e.message;persistEdits();toast(e.message,true);restoreEdits();}}
function bindSettings(){$('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{let logo='';const file=$('#logo-file').files?.[0];if(file){if(file.type!=='image/png'||file.size>500000)throw Error('เลือก PNG ขนาดไม่เกิน 500 KB');logo=await readPNG(file);}const saveSettings=()=>mutate('แก้ไขรูปแบบรายงาน',s=>{s.settings.organization=f.get('organization');s.settings.reportTitles={DOH:f.get('titleDOH').trim(),PROVINCE:f.get('titleProvince').trim()};s.settings.title=s.settings.reportTitles.DOH;s.settings.systemName=String(f.get('systemName')).trim();if(f.get('removeLogo'))s.settings.logo='';if(logo)s.settings.logo=logo;});if(f.get('removeLogo'))confirmAction('ยืนยันลบโลโก้','ลบโลโก้ปัจจุบันออกจากระบบและบันทึกการตั้งค่านี้',saveSettings);else await saveSettings();}catch(err){toast(err.message,true);}});$('#cloud-form')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;const f=new FormData(e.target);try{cloud.setConfig(f.get('url'),f.get('key'));const data=await loadWorkspace();if(data){validateLoadedWorkspace(data);state=data;selected=state.reports[0].id;year=state.years[0];await cacheWorkspace(state);cloudMode=true;render();toast('โหลดข้อมูลจาก Supabase แล้ว ไม่ต้องเข้าสู่ระบบ');}else{state.revision=0;cloudMode=true;render();toast('เชื่อมต่อแล้ว ฐานข้อมูลยังว่าง กดนำเข้าข้อมูล JSON เพื่อเริ่มใช้งาน');}}catch(err){toast(err.message,true);}finally{b.disabled=false;}});}
