function segmentsEditorHTML(r){return `<div class="registry-section route-editor">${['routeNumber','controlSection','sectionName'].map(k=>`<datalist id="road-list-${k}">${[...new Set((state.settings.roadSections||[]).map(r=>r[k]).filter(Boolean))].map(v=>`<option value="${esc(v)}">`).join('')}</datalist>`).join('')}<div class="table-scroll"><table class="segment-edit-table"><caption>ช่วงทางของสัญญา — กดแก้ไขที่สายที่ต้องการ</caption><thead><tr><th>สาย / ช่วง</th>${segmentFields.slice(0,6).map(([,label])=>`<th scope="col">${label}</th>`).join('')}<th>จัดการ</th></tr></thead><tbody id="segment-rows">${(r.segments||[]).map((seg,i)=>segmentRowHTML(seg,i)).join('')}</tbody></table></div><p class="hint" data-segments-empty ${(r.segments||[]).length?'hidden':''}>ยังไม่มีช่วงทาง เพิ่มสาย / ช่วงทางได้โดยไม่ต้องสร้างสัญญาใหม่</p><button type="button" class="btn" id="add-registry-segment">+ เพิ่มสาย / ช่วงทาง</button><p class="hint">กรอกหลายสายภายใต้ ID Code เดียวกัน แล้วกดบันทึกสัญญาเพื่อบันทึกทั้งหมด</p><p class="hint" role="status" id="segment-status"></p></div>`;}
function bindSegmentEditor(){const container=$('#segment-rows');if(!container)return;const rows=()=>[...container.querySelectorAll('[data-segment-index]')],editorFor=row=>container.querySelector('[data-segment-editor-for="'+row.dataset.segmentIndex+'"]'),renumber=()=>{rows().forEach((row,i)=>{row.querySelector('[data-segment-number]').textContent='สาย / ช่วงที่ '+(i+1);row.querySelector('[data-edit-segment]').setAttribute('aria-label','แก้ไขสาย / ช่วงที่ '+(i+1));row.querySelector('[data-remove-segment]').setAttribute('aria-label','นำสาย / ช่วงที่ '+(i+1)+' ออก');});$('[data-segments-empty]').hidden=rows().length>0;},refresh=row=>{const editor=editorFor(row);for(const [key]of segmentFields.slice(0,6))row.querySelector('[data-segment-value="'+key+'"]').textContent=editor.querySelector('[name="seg_'+row.dataset.segmentIndex+'_'+key+'"]').value.trim()||'ยังไม่ระบุ';};container.addEventListener('input',e=>{const editor=e.target.closest('[data-segment-editor-for]');if(editor)refresh(container.querySelector('[data-segment-index="'+editor.dataset.segmentEditorFor+'"]'));});container.onclick=e=>{const button=e.target.closest('button');if(!button)return;const owner=button.closest('[data-segment-index],[data-segment-editor-for]'),index=owner?.dataset.segmentIndex??owner?.dataset.segmentEditorFor,row=container.querySelector('[data-segment-index="'+index+'"]');if(!row)return;const editor=editorFor(row),confirm=editor.querySelector('.segment-remove-confirm');if(button.hasAttribute('data-edit-segment')){editor.hidden=false;button.setAttribute('aria-expanded','true');editor.querySelector('input').focus();}if(button.hasAttribute('data-finish-segment')){refresh(row);editor.hidden=true;row.querySelector('[data-edit-segment]').setAttribute('aria-expanded','false');row.querySelector('[data-edit-segment]').focus();}if(button.hasAttribute('data-remove-segment')){editor.hidden=false;row.querySelector('[data-edit-segment]').setAttribute('aria-expanded','true');confirm.hidden=false;confirm.querySelector('[data-cancel-remove-segment]').focus();}if(button.hasAttribute('data-cancel-remove-segment')){confirm.hidden=true;row.querySelector('[data-remove-segment]').focus();}if(button.hasAttribute('data-confirm-remove-segment')){row.remove();editor.remove();renumber();$('#segment-status').textContent='นำช่วงทางออกจากรายการแก้ไขแล้ว ยังไม่ได้บันทึก';$('#add-registry-segment').focus();}};$('#add-registry-segment').onclick=()=>{const index=Math.max(-1,...rows().map(row=>+row.dataset.segmentIndex))+1;container.insertAdjacentHTML('beforeend',segmentRowHTML({},index,true));renumber();$('#segment-status').textContent='เพิ่มช่องกรอกช่วงทางแล้ว ยังไม่ได้บันทึก';container.lastElementChild.querySelector('input').focus();};renumber();}
function readSegmentForm(f,r){return segmentsFromForm(f);}

function personnelRowHTML(member,group,index,open=false){const token=group+'_'+index,ordinal=member.ordinal||index+1;return `<tr data-person-row="${token}"><th scope="row" data-person-ordinal>${ordinal}</th><td data-person-name>${esc(member.name||'ยังไม่ระบุ')}</td><td data-person-position>${esc(member.position||'ยังไม่ระบุ')}</td><td data-person-duty>${esc(member.duty||personnelDuty(group,ordinal))}</td><td><div class="row-actions"><button type="button" class="btn" data-edit-person aria-expanded="${open}" aria-controls="person-editor-${token}">แก้ไข</button><button type="button" class="btn danger" data-remove-person>ลบ</button></div></td></tr><tr id="person-editor-${token}" data-person-editor="${token}" ${open?'':'hidden'}><td colspan="5"><div class="segment-fields"><div class="form-grid">${selectField('ประเภทบุคลากร','person_'+token+'_group',[{value:'inspection',label:'คณะกรรมการตรวจรับพัสดุ'},{value:'supervision',label:'ผู้ควบคุมงาน'}],group)}${field('ลำดับ','person_'+token+'_ordinal',ordinal,'number','required min="1" step="1"')}${field('ชื่อ–สกุล','person_'+token+'_name',member.name||'','text','required list="personnel-full-names"')}${field('ตำแหน่ง','person_'+token+'_position',member.position||'')}${selectField('บทบาท','person_'+token+'_duty',group==='inspection'?['ประธาน','กรรมการ']:['ผู้ควบคุมงาน','ผู้ช่วยผู้ควบคุมงาน'],member.duty||personnelDuty(group,ordinal))}</div><button type="button" class="btn" data-finish-person>เสร็จสิ้นการกรอกบุคลากร</button><p class="form-error" role="alert"></p><div class="person-remove-confirm" hidden><p>ลบรายชื่อออกจากสัญญานี้หรือไม่? ไม่ลบบุคคลจากข้อมูลพื้นฐาน และจะบันทึกเมื่อกดบันทึกสัญญา</p><button type="button" class="btn danger" data-confirm-remove-person>ยืนยันลบจากสัญญา</button><button type="button" class="btn" data-cancel-remove-person>เก็บรายชื่อไว้</button></div></div></td></tr>`;}
function personnelEditorHTML(r){return `<div class="personnel-editor"><datalist id="personnel-full-names">${state.supervisors.map(p=>`<option value="${esc(p.name)}">`).join('')}</datalist>${[['inspection','คณะกรรมการตรวจรับพัสดุ'],['supervision','ผู้ควบคุมงาน']].map(([group,label])=>`<section class="registry-section"><h4>${label}</h4><div class="table-scroll"><table class="personnel-edit-table"><thead><tr><th>ลำดับ</th><th>ชื่อ–สกุล</th><th>ตำแหน่ง</th><th>บทบาท</th><th>จัดการ</th></tr></thead><tbody data-person-group="${group}">${assignmentDetails(state,r,group).map((m,i)=>personnelRowHTML(m,group,i)).join('')}</tbody></table></div><button type="button" class="btn" data-add-person="${group}">+ เพิ่ม${label}</button></section>`).join('')}<p class="hint">ชื่อใช้ทะเบียนบุคลากรร่วมกัน ตำแหน่ง ลำดับ และบทบาทเก็บเฉพาะสัญญานี้</p><p class="hint" role="status" id="personnel-editor-status"></p></div>`;}
function bindPersonnelEditor(){const root=$('.personnel-editor');if(!root)return;const locate=token=>({row:root.querySelector('[data-person-row="'+token+'"]'),editor:root.querySelector('[data-person-editor="'+token+'"]')}),input=(e,key)=>e.querySelector('[name$=_'+key+']'),summary=token=>{const {row,editor}=locate(token);for(const key of ['ordinal','name','position','duty'])row.querySelector('[data-person-'+key+']').textContent=input(editor,key).value||'ยังไม่ระบุ';};root.oninput=e=>{const editor=e.target.closest('[data-person-editor]');if(editor)summary(editor.dataset.personEditor);};root.onchange=e=>{const editor=e.target.closest('[data-person-editor]');if(!editor)return;if(e.target.name.endsWith('_group')){const group=e.target.value,ordinal=root.querySelector('[data-person-group="'+group+'"]').querySelectorAll('[data-person-row]').length+1;input(editor,'ordinal').value=ordinal;input(editor,'duty').innerHTML=(group==='inspection'?['ประธาน','กรรมการ']:['ผู้ควบคุมงาน','ผู้ช่วยผู้ควบคุมงาน']).map(x=>`<option>${x}</option>`).join('');input(editor,'duty').value=personnelDuty(group,ordinal);}summary(editor.dataset.personEditor);};root.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.addPerson){const group=b.dataset.addPerson,tbody=root.querySelector('[data-person-group="'+group+'"]'),index=Math.max(-1,...[...root.querySelectorAll('[data-person-row]')].map(x=>+x.dataset.personRow.split('_').at(-1)))+1,ordinal=tbody.querySelectorAll('[data-person-row]').length+1;tbody.insertAdjacentHTML('beforeend',personnelRowHTML({ordinal},group,index,true));tbody.lastElementChild.querySelector('[name$=_name]').focus();$('#personnel-editor-status').textContent='เพิ่มช่องกรอกแล้ว ยังไม่ได้บันทึก';return;}const owner=b.closest('[data-person-row],[data-person-editor]'),token=owner?.dataset.personRow||owner?.dataset.personEditor;if(!token)return;const {row,editor}=locate(token),confirm=editor.querySelector('.person-remove-confirm');if(b.hasAttribute('data-edit-person')){editor.hidden=false;b.setAttribute('aria-expanded','true');input(editor,'name').focus();}if(b.hasAttribute('data-finish-person')){if(!input(editor,'name').value.trim()){editor.querySelector('.form-error').textContent='กรุณาระบุชื่อ–สกุล';input(editor,'name').focus();return;}summary(token);const target=root.querySelector('[data-person-group="'+input(editor,'group').value+'"]');if(row.parentNode!==target){target.append(row,editor);}editor.hidden=true;row.querySelector('[data-edit-person]').setAttribute('aria-expanded','false');row.querySelector('[data-edit-person]').focus();}if(b.hasAttribute('data-remove-person')){editor.hidden=false;row.querySelector('[data-edit-person]').setAttribute('aria-expanded','true');confirm.hidden=false;confirm.querySelector('[data-cancel-remove-person]').focus();}if(b.hasAttribute('data-cancel-remove-person')){confirm.hidden=true;row.querySelector('[data-remove-person]').focus();}if(b.hasAttribute('data-confirm-remove-person')){const group=row.parentNode.dataset.personGroup;row.remove();editor.remove();const tbody=root.querySelector('[data-person-group="'+group+'"]');[...tbody.querySelectorAll('[data-person-row]')].forEach((r,i)=>{const e=locate(r.dataset.personRow).editor;input(e,'ordinal').value=i+1;input(e,'duty').value=personnelDuty(group,i+1);summary(r.dataset.personRow);});root.querySelector('[data-add-person="'+group+'"]').focus();$('#personnel-editor-status').textContent='นำรายชื่อออกจากรายการแก้ไขแล้ว ยังไม่ได้บันทึก';}};}

function personnelImportDialog(){let records=[],preview=[],sourceName='';modal('นำเข้าคณะกรรมการตรวจรับพัสดุและผู้ควบคุมงาน · ก-4',`<form id="personnel-import"><p class="hint">อ่านเฉพาะรายชื่อคณะกรรมการตรวจรับพัสดุและผู้ควบคุมงาน จับคู่ ID Code ในปีและกลุ่มงบที่เลือก ไม่ทับรหัสงานหรือข้อมูลสัญญาจาก ก-3 แยกชื่อ ตำแหน่งในวงเล็บ และลำดับ กำหนดประธาน/กรรมการและผู้ควบคุม/ผู้ช่วยตามลำดับ ชื่อเดิมใช้คีย์เดิม</p><div class="form-grid">${selectField('กลุ่มงบ','funding',state.fundingSources.map(x=>({value:x.id,label:x.name})),funding)}${selectField('ปีงบประมาณ','year',state.years,year)}<label class="field wide">ไฟล์ ก-4 (.xlsx)<input id="personnel-file" type="file" accept=".xlsx" required></label></div><button class="btn primary" id="read-personnel" type="button">อ่านและตรวจรายชื่อ</button><div id="personnel-preview"></div><p class="form-error" role="alert"></p></form>`);const form=$('#personnel-import');$('#read-personnel').onclick=async()=>{const b=$('#read-personnel');b.disabled=true;try{const file=$('#personnel-file').files[0];if(!file)throw Error('เลือกไฟล์ ก-4 ก่อน');records=(await readG3Workbook(await file.arrayBuffer(),'personnel')).records;sourceName=file.name;show();}catch(e){showFormError(form,e.message);}finally{b.disabled=false;}};const show=()=>{preview=previewPersonnelImport(state,records,+form.elements.year.value,form.elements.funding.value);$('#personnel-preview').innerHTML=`<div class="notice">อ่าน ${preview.length} โครงการ · มีปัญหา ${preview.filter(x=>x.errors.length).length} · เปลี่ยน ${preview.filter(x=>x.changes.length&&!x.errors.length).length}</div><div class="table-scroll"><table data-selection-key="import-personnel" data-selection-ids="${esc(JSON.stringify(preview.map(x=>String(x.index))))}"><thead><tr><th>ID Code / สัญญา</th><th>คณะกรรมการตรวจรับพัสดุ</th><th>ผู้ควบคุมงาน</th><th>ผลตรวจ</th></tr></thead><tbody>${preview.map(x=>`<tr data-select-id="${x.index}"><td>${esc(x.record.sourceId)}<br>${esc(x.record.contract)}</td><td>${x.record.committeeMembers.map(a=>esc(a.ordinal+'. '+a.name+' · '+(a.position||'ยังไม่ระบุตำแหน่ง')+' · '+a.duty)).join('<br>')}</td><td>${x.record.supervisorMembers.map(a=>esc(a.ordinal+'. '+a.name+' · '+(a.position||'ยังไม่ระบุตำแหน่ง')+' · '+a.duty)).join('<br>')}</td><td>${esc(x.errors.join(' · ')||(!x.changes.length?'เหมือนเดิม · ไม่เขียนซ้ำ':'พร้อมอัปเดต'))}${!x.errors.length?csvChangeHTML(x.changes,state):''}</td></tr>`).join('')}</tbody></table></div><div class="dialog-actions"><button type="button" class="btn primary" id="commit-personnel">นำเข้ารายชื่อและเชื่อมสัญญา</button></div>`;tableSelections.delete('import-personnel');mountSelections();$('#commit-personnel').onclick=()=>commitCSVForm($('#commit-personnel'),async()=>{const chosen=selectionFor('import-personnel',preview.map(x=>String(x.index)));let result;await mutate('นำเข้าคณะกรรมการและผู้ควบคุมงาน',s=>{const before=cloneForMutation(s);result=applyPersonnelImport(s,preview,chosen);Object.assign(s,result.state);if(result.updated)captureImportResult(s,'contractRegistry',before,sourceName);},{format:'XLSX',fileName:sourceName});$('#modal').close();render();toast(`เชื่อม ${result.updated} สัญญา · บุคคลใหม่ ${result.created} · เหมือนเดิม ${result.unchanged}`);},e=>showFormError(form,e.message));};form.elements.year.onchange=()=>records.length&&show();form.elements.funding.onchange=()=>records.length&&show();$('#personnel-file').onchange=()=>{records=[];preview=[];$('#personnel-preview').innerHTML='';};}

function roadLibraryDialog(query='',page=1){const roads=state.settings.roadSections||[],filtered=roads.filter(r=>[r.routeNumber,r.controlSection,r.sectionName].join(' ').toLowerCase().includes(query.toLowerCase())),pages=Math.max(1,Math.ceil(filtered.length/25));page=Math.min(page,pages);modal('ข้อมูลพื้นฐาน · ทางหลวงและตอนควบคุม',`<p class="hint">เพิ่มอัตโนมัติจากช่วงทางที่นำเข้าและบันทึก กม.และทิศทางเก็บแยกตามสัญญา การแก้ข้อมูลกลางไม่เปลี่ยนสัญญาเก่า</p><label class="field">ค้นหาทางหลวง / ตอนควบคุม<input id="road-master-search" value="${esc(query)}"></label><div class="actions"><button type="button" class="btn primary" id="new-road-master">+ เพิ่มตอนทางหลวง</button><button type="button" class="btn" id="export-road-master">ส่งออก CSV</button></div><div class="table-scroll"><table><thead><tr><th>ทางหลวง</th><th>ตอนควบคุม</th><th>ชื่อตอน / โครงการ</th><th>จัดการ</th></tr></thead><tbody>${filtered.slice((page-1)*25,page*25).map(r=>`<tr><td>${esc(r.routeNumber)}</td><td>${esc(r.controlSection)}</td><td>${esc(r.sectionName)}</td><td><div class="row-actions"><button type="button" class="btn" data-edit-road-master="${esc(r.id)}">แก้ไข</button><button type="button" class="btn danger" data-delete-road-master="${esc(r.id)}">ลบ</button></div></td></tr>`).join('')||'<tr><td colspan="4">ยังไม่มีข้อมูล เพิ่มอัตโนมัติเมื่อนำเข้า ก-3 หรือเพิ่มช่วงทาง</td></tr>'}</tbody></table></div><div class="table-foot"><span>${filtered.length} รายการ · หน้า ${page} / ${pages}</span><div class="actions"><button type="button" class="btn" id="road-master-prev" ${page<=1?'disabled':''}>ก่อนหน้า</button><button type="button" class="btn" id="road-master-next" ${page>=pages?'disabled':''}>ถัดไป</button></div></div>`);$('#road-master-prev').onclick=()=>roadLibraryDialog(query,page-1);$('#road-master-next').onclick=()=>roadLibraryDialog(query,page+1);$('#road-master-search').oninput=e=>{const value=e.target.value,pos=e.target.selectionStart;roadLibraryDialog(value,1);$('#road-master-search').focus();$('#road-master-search').setSelectionRange(pos,pos);};$('#new-road-master').onclick=()=>roadMasterEdit();$('#export-road-master').onclick=()=>{const q=v=>'"'+String(v||'').replace(/"/g,'""')+'"';download('\ufeff'+[['หมายเลขทางหลวง','ตอนควบคุม','ชื่อตอน/โครงการ'],...filtered.map(r=>[r.routeNumber,r.controlSection,r.sectionName])].map(r=>r.map(q).join(',')).join('\r\n'),'ทางหลวงและตอนควบคุม.csv','text/csv;charset=utf-8');};$$('[data-edit-road-master]').forEach(b=>b.onclick=()=>roadMasterEdit(b.dataset.editRoadMaster));$$('[data-delete-road-master]').forEach(b=>b.onclick=()=>{const item=roads.find(r=>r.id===b.dataset.deleteRoadMaster),used=state.contractRegistry.some(r=>r.segments?.some(seg=>['routeNumber','controlSection','sectionName'].every(k=>(seg[k]||'')===(item[k]||''))));if(used)return toast('ตอนทางหลวงนี้ยังใช้ในสัญญา ไม่สามารถลบได้',true);confirmAction('ลบตอนทางหลวง '+item.routeNumber+' '+item.controlSection,'ลบเฉพาะข้อมูลพื้นฐานรายการที่ไม่ถูกใช้งาน',()=>mutate('ลบตอนทางหลวง',s=>{s.settings.roadSections=s.settings.roadSections.filter(r=>r.id!==item.id);}));});}
function roadMasterEdit(id){const existing=state.settings.roadSections?.find(r=>r.id===id)||{};modal(id?'แก้ไขตอนทางหลวง':'เพิ่มตอนทางหลวง',`<form novalidate><div class="form-grid">${field('หมายเลขทางหลวง','routeNumber',existing.routeNumber||'','text','required')}${field('ตอนควบคุม','controlSection',existing.controlSection||'')}${field('ชื่อตอน / โครงการ','sectionName',existing.sectionName||'')}</div>${buttons('บันทึกตอนทางหลวง')}</form>`,f=>mutate('บันทึกข้อมูลพื้นฐานทางหลวง',s=>{const record={id:id||'ROAD-'+uid(),...Object.fromEntries(['routeNumber','controlSection','sectionName'].map(k=>[k,String(f.get(k)||'').trim()]))};s.settings.roadSections||=[];if(s.settings.roadSections.some(r=>r.id!==id&&['routeNumber','controlSection','sectionName'].every(k=>r[k]===record[k])))throw Error('มีตอนทางหลวงนี้อยู่แล้ว');const index=s.settings.roadSections.findIndex(r=>r.id===id);if(index>=0)s.settings.roadSections[index]=record;else s.settings.roadSections.push(record);}));}
function personnelLibraryDialog(role='inspection'){const people=state.supervisors.filter(x=>x.personRoles?.includes(role));modal(role==='inspection'?'ข้อมูลพื้นฐาน · คณะกรรมการตรวจรับพัสดุ':'ข้อมูลพื้นฐาน · ผู้ควบคุมงาน',`<p class="hint">ชื่อเต็มใช้เชื่อมหลายสัญญา โดยไม่สร้างบุคคลซ้ำ</p><button class="btn" type="button" id="export-personnel-library">ส่งออกรายชื่อ CSV</button><div class="table-scroll"><table><thead><tr><th>ชื่อบุคคล</th><th>สัญญาที่เกี่ยวข้อง</th></tr></thead><tbody>${people.map(p=>`<tr><td>${esc(p.name)}</td><td>${state.contractRegistry.filter(r=>(role==='inspection'?r.committeeIds:r.supervisorIds)?.includes(p.id)).length}</td></tr>`).join('')||'<tr><td colspan="2">ยังไม่มีรายชื่อ นำเข้าแบบ ก-4 เพื่อเพิ่มได้</td></tr>'}</tbody></table></div>`);$('#export-personnel-library').onclick=()=>{download(masterCSV({...state,supervisors:people},'supervisors'),'คณะกรรมการตรวจรับพัสดุ.csv','text/csv;charset=utf-8');void logActivity('ส่งออกรายชื่อคณะกรรมการ CSV',[],{count:people.length});};}
function registryTable(all){all||=registryVisibleRecords();const rows=all.filter(r=>(!budgetFilter||(r.budgetAccount||'ยังไม่ระบุ')===budgetFilter)&&(!query||[r.sourceId,r.contract,r.title,r.workCode,r.budgetAccount,r.contractorRaw,r.contractorName,...personnelNames(state,r)].join(' ').toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>compareData(a,b,registrySort.key,registrySort.dir));const pages=Math.max(1,Math.ceil(rows.length/12));page=Math.min(page,pages);return `<div class="card registry-panel"><div class="filters"><input id="registry-search" class="search" aria-label="ค้นหาทะเบียน" placeholder="ค้นหา ID Code เลขสัญญา ชื่องาน ผู้รับจ้าง" value="${esc(query)}"><span class="sub">${rows.length} สัญญา</span></div><div class="table-scroll"><table class="registry-table" data-selection-key="registry:${funding}:${year}" data-selection-ids="${esc(JSON.stringify(rows.map(x=>x.id)))}"><thead><tr>${[['ID Code','sourceId'],['เลขสัญญา','contract'],['รหัสงาน','workCode'],['ชื่องาน','title'],['ผู้รับจ้าง','contractorName'],['ผู้ควบคุมงาน','supervisor']].map(([l,k])=>sortHead(l,k,'registry',registrySort)).join('')}<th>จัดการ</th></tr></thead><tbody>${rows.slice((page-1)*12,page*12).map(r=>`<tr data-registry-row="${r.id}" tabindex="0" aria-label="ดูสัญญา ${esc(r.contract)}"><td class="source-code">${esc(r.sourceId||'–')}</td><td><strong>${esc(r.contract)}</strong><div>${dataChangeBadge(r)}${registryExpired(state,r)?'<span class="pill warn">หมดอายุสัญญาแล้ว</span>':''}</div></td><td>${esc(r.workCode||'–')}</td><td>${esc(r.title)}<div class="sub">ผลงานล่าสุด ${registryCurrent(state,r).currentActual.toFixed(2)}%</div></td><td>${esc(r.contractorName||'–')}</td><td>${personnelNames(state,r).map(x=>esc(x)).join('<br>')||'–'}</td><td><div class="row-actions">${iconButton('view','ดูสัญญา',`data-registry-view="${r.id}"`)}${iconButton('edit','แก้ไขสัญญา',`data-registry-edit="${r.id}"`)}${iconButton('delete','ลบสัญญา',`data-registry-delete="${r.id}"`)}</div></td></tr>`).join('')||'<tr><td colspan="8" class="empty">ไม่มีสัญญาตามตัวกรองนี้</td></tr>'}</tbody></table></div><div class="table-foot"><span>หน้า ${page} / ${pages}</span><div class="actions"><button class="btn" data-registry-page="${page-1}" ${page<=1?'disabled':''}>ก่อนหน้า</button><button class="btn" data-registry-page="${page+1}" ${page>=pages?'disabled':''}>ถัดไป</button></div></div></div>`;}

function registryDelete(id){const r=state.contractRegistry.find(x=>x.id===id);if(!r)return;confirmAction('ยืนยันลบสัญญา '+r.contract,'นำสัญญานี้ออกจากทะเบียนและสัปดาห์ใหม่ หากมีรายงานเดิม ระบบจะเก็บประวัติรายงานนั้นไว้',async()=>{await mutate('ลบสัญญา '+r.contract,s=>deleteRegistryRecord(s,id));});}
function registryDetailDialog(id){const r=findRegistryRecord(id);if(!r)return;modal('รายละเอียดสัญญา',registryDetailHTML(state,r)+`<div class="dialog-actions record-actions"><button type="button" class="btn danger" id="detail-delete">ลบสัญญา</button><button type="button" class="btn" id="detail-close">ปิด</button><button type="button" class="btn primary" id="detail-edit">แก้ไขสัญญา</button></div>`);$('#modal').style.width='1040px';$('#detail-edit').onclick=()=>registryEditDialog(r.id);$('#detail-delete').onclick=()=>registryDelete(r.id);$('#detail-close').onclick=()=>$('#modal').close();const openRoute=(index,remove=false)=>{registryEditDialog(r.id);const row=$('#segment-rows [data-segment-index="'+index+'"]');row?.querySelector(remove?'[data-remove-segment]':'[data-edit-segment]').click();};$$('[data-open-route-editor]').forEach(b=>b.onclick=()=>openRoute(+b.dataset.openRouteEditor));$$('[data-request-route-delete]').forEach(b=>b.onclick=()=>openRoute(+b.dataset.requestRouteDelete,true));$('#detail-add-route').onclick=()=>{registryEditDialog(r.id);$('#add-registry-segment').click();};}

function registryMasterField(label,name,key,value,required=false){return `<label class="field">${label}<div class="master-control"><input name="${name}" value="${esc(value||'')}" ${required?'required':''} list="registry-list-${key}" autocomplete="off" data-master-key="${key}"><button type="button" class="btn inline-add" data-registry-add-master="${key}" hidden>เพิ่มชื่อนี้</button></div><datalist id="registry-list-${key}"></datalist></label>`;}
function registryEditDialog(id){const existing=findRegistryRecord(id),r=existing||{id:'REG-'+uid(),year,funding,start:today(),end:today(),duration:90,extensions:[]};const masterName=(key,id)=>state[key].find(x=>x.id===id)?.name||'';modal(existing?'แก้ไขสัญญา · '+r.contract:'เพิ่มสัญญาใหม่',`<form id="contract-form" novalidate><p class="hint">จัดกลุ่มข้อมูลตามรายละเอียดสัญญา วันที่แสดงตามการตั้งค่าของอุปกรณ์ และบันทึกเป็นวันที่มาตรฐาน</p><h3>รายละเอียดโครงการ</h3><div class="form-grid">${field('ID Code จากแพลนเน็ต','sourceId',r.sourceId||'','text')}${selectField('กลุ่มงบ','funding',state.fundingSources.map(x=>({value:x.id,label:x.name})),r.funding)}${selectField('ปีงบประมาณ','year',state.years,r.year)}${registryMasterField('รหัสงาน','workCode','workCodes',r.workCode)}${registryMasterField('ประเภทงาน (เว้นว่างได้)','workTypeName','workTypes',masterName('workTypes',r.workTypeId))}${registryMasterField('ลักษณะงาน / ชื่องาน','title','workNames',r.title,true)}</div><h3>สัญญาและระยะเวลา</h3><div class="form-grid">${field('เลขสัญญา','contract',r.contract||'','text','required')}${field('วันที่ลงนาม','signedAt',r.signedAt||'','date')}${field('เริ่มต้นสัญญา','start',r.start,'date','required')}${field('วันสิ้นสุดปัจจุบัน','end',r.end,'date','required')}${field('ระยะเวลาเดิม (วัน)','duration',r.duration,'number','required min="1" step="1"')}</div>${existing?`<p class="hint">สิ้นสุดเดิม ${fmt(r.originalEnd||r.end)} · ขยายอนุมัติแล้ว ${(r.extensions||[]).filter(x=>x.approved).reduce((n,x)=>n+x.days,0)} วัน ใช้ปุ่มบันทึกการขยายสัญญาสำหรับเพิ่มการอนุมัติ</p>`:''}<h3>งบประมาณและวงเงิน</h3><div class="form-grid">${registryMasterField('บัญชีงบประมาณ','budgetAccount','budgetAccounts',r.budgetAccount)}${['budgetAct','allocatedBudget'].map(k=>field(financeLabels.find(x=>x[0]===k)[1]+' (บาท)',k,r[k]??'','number','min="0" step="0.01"')).join('')}${field('วงเงินค่างานตามสัญญา (บาท)','contractValue',r.contractValue??'','number','min="0" step="0.01"')}${['poAmount','carryBudget'].map(k=>field(financeLabels.find(x=>x[0]===k)[1]+' (บาท)',k,r[k]??'','number','min="0" step="0.01"')).join('')}</div><h3>การเบิกจ่าย</h3><div class="form-grid">${['paidFiscal','paidCarry'].map(k=>field(financeLabels.find(x=>x[0]===k)[1]+' (บาท)',k,r[k]??'','number','min="0" step="0.01"')).join('')}${field('ยอดเบิกจ่ายรวมโครงการ (บาท)','actualCost',r.actualCost??'','number','min="0" step="0.01"')}${field('วันที่เบิกเงินงวดสุดท้าย','finalPaymentDate',r.finalPaymentDate||'','date')}${selectField('สถานะเบิกจ่าย','payment',['รอส่งมอบงาน','รอเบิกจ่าย','เบิกจ่ายแล้ว'],r.payment||latestContractEntry(state,r)?.entry?.payment||'รอส่งมอบงาน')}</div><p class="hint">เดือน / ปีเบิกจ่ายตามต้นฉบับ: ${esc(r.paymentMonth||'ยังไม่ระบุ')} — ไม่ใช้แทนวันที่เบิกจ่ายจริง</p><h3>ความก้าวหน้าและการส่งมอบ</h3><p class="hint">ผลงานสะสมล่าสุด ${registryCurrent(state,r).currentActual}% · ปรับผลงานในหน้าอัปเดตรายสัปดาห์</p><div class="form-grid">${field('วันส่งมอบงาน','deliveryDate',r.deliveryDate||'','date')}${field('วันตรวจรับงาน','acceptanceDate',r.acceptanceDate||'','date')}</div><h3>ผู้รับจ้างและบุคลากร</h3>${r.contractorNeedsReview?`<p class="notice">ชื่อผู้ดำเนินการตามต้นฉบับ: ${esc(r.contractorRaw)}</p>`:''}<div class="form-grid">${registryMasterField('ผู้รับจ้าง','contractorName','contractors',masterName('contractors',r.contractorId))}</div>${personnelEditorHTML(r)}<h3>ช่วงทางและปริมาณงาน</h3><div class="form-grid">${field('ปริมาณงาน','quantity',r.quantity??'','number','min="0" step="0.0001"')}${field('หน่วยนับ','unit',r.unit||'')}</div>${segmentsEditorHTML(r)}<h3>หมายเหตุและข้อมูลเพิ่มเติม</h3><div class="form-grid">${field('หมายเหตุทะเบียน / รายงานล่าสุด','note',r.note||'','textarea')}${(state.settings.customFields||[]).map(c=>field(c.name,'extra_'+c.id,r.extras?.[c.id]||'')).join('')}</div><p class="hint">รายงานเก่าที่ปิดแล้วเก็บข้อมูล ณ สัปดาห์นั้นไว้ การแก้ทะเบียนใช้กับข้อมูลปัจจุบันและสัปดาห์ใหม่</p><p class="form-error" role="alert"></p><div class="dialog-actions">${existing?'<button type="button" class="btn danger" id="contract-delete">ลบสัญญา</button>':''}<button type="button" class="btn" data-cancel-contract>ยกเลิก</button><button type="submit" class="btn primary">บันทึกสัญญา</button></div></form>${existing?'<div class="actions"><button type="button" class="btn" id="registry-extension">บันทึกการขยายสัญญา</button></div>':''}`,f=>mutate(existing?'แก้ไขทะเบียนสัญญา':'เพิ่มทะเบียนสัญญา',s=>{
 const n={...clone(existing?s.contractRegistry.find(x=>x.id===r.id):r),year:+f.get('year'),funding:String(f.get('funding'))};for(const k of ['sourceId','contract','title','workCode','budgetAccount','signedAt','start','end','unit','finalPaymentDate','deliveryDate','acceptanceDate'])n[k]=String(f.get(k)||'').trim();for(const k of ['duration','contractValue','actualCost','quantity'])n[k]=f.get(k)===''?'':+f.get(k);
 n.extras={...r.extras};for(const c of(s.settings.customFields||[]))n.extras[c.id]=String(f.get('extra_'+c.id)||'');for(const [key,input,link]of [['budgetAccounts','budgetAccount','budgetAccountId'],['workCodes','workCode','workCodeId'],['workNames','title','workNameId'],['workTypes','workTypeName','workTypeId'],['contractors','contractorName','contractorId'],['supervisors','supervisorName','supervisorId']]){const name=String(f.get(input)||'').trim(),item=s[key].find(x=>x.name===name&&(!x.archived||x.id===r[link]));if(name&&!item){const created={id:key.toUpperCase()+'-'+uid(),name};s[key].push(created);n[link]=created.id;}else n[link]=item?.id||'';}
 if(!n.contractorId&&!n.contractorRaw)throw Error('เลือกผู้รับจ้าง หรือเพิ่มชื่อผู้รับจ้างก่อน');if(n.contractorId&&(!r.contractorNeedsReview||!n.contractorRaw))n.contractorRaw=s.contractors.find(x=>x.id===n.contractorId)?.name||n.contractorRaw||'';n.contractorNeedsReview=!n.contractorId;
 n.note=String(f.get('note')||'');n.payment=String(f.get('payment')||'รอส่งมอบงาน');if(n.payment==='เบิกจ่ายแล้ว'&&(!n.finalPaymentDate||registryCurrent(s,r).currentActual<100))throw Error('เบิกจ่ายแล้วต้องมีผลงานสะสม 100% และวันที่เบิกจ่ายครบ');for(const key of ['budgetAct','allocatedBudget','poAmount','carryBudget','paidFiscal','paidCarry']){const raw=f.get(key);n[key]=raw===''?'':Number(raw);if(raw!==''&&(!Number.isFinite(n[key])||n[key]<0))throw Error('วงเงินต้องเป็นตัวเลขไม่ติดลบ');}n.segments=readSegmentForm(f,r);const members=personnelFromForm(f);for(const group of ['inspection','supervision'])setContractPersonnel(s,n,group,members[group]);if(r.personnelImported||n.supervisorIds?.length){n.supervisorId=n.supervisorIds?.[0]||'';n.supervisor=s.supervisors.find(x=>x.id===n.supervisorId)?.name||'';}const check=previewRegistryImport(s,[n],n.year,n.funding)[0];if(check.errors.length)throw Error(check.errors.join(', '));validateDates({deliveryDate:n.deliveryDate,acceptanceDate:n.acceptanceDate,paymentDate:n.finalPaymentDate,payment:n.finalPaymentDate?'เบิกจ่ายแล้ว':'รอเบิกจ่าย'});
 if(s.contractRegistry.some(x=>x.id!==n.id&&x.year===n.year&&(x.funding||'DOH')===n.funding&&contractKey(x.contract)===contractKey(n.contract)))throw Error('เลขสัญญาซ้ำในกลุ่มงบและปีนี้');const p=s.projects.find(x=>x.id===r.projectId);if(p&&s.reports.some(x=>x.entries[p.id])&&(p.year!==n.year||(p.funding||'DOH')!==n.funding))throw Error('สัญญามีรายงานแล้ว ไม่สามารถย้ายกลุ่มงบหรือปีได้');n.originalEnd=addDays(n.end,-(n.extensions||[]).filter(x=>x.approved).reduce((total,x)=>total+x.days,0));n.updatedAt=new Date().toISOString();const i=s.contractRegistry.findIndex(x=>x.id===n.id);if(i<0)s.contractRegistry.push(n);else s.contractRegistry[i]=n;
 const job=s.workNames.find(x=>x.id===n.workNameId);if(job){job.typeId=n.workTypeId;job.codeIds||=[];if(n.workCodeId&&!job.codeIds.includes(n.workCodeId))job.codeIds.push(n.workCodeId);}
 if(p){const projection=projectFromRegistry(s,n);s.projects[s.projects.findIndex(x=>x.id===p.id)]=projection;for(const draft of s.reports.filter(x=>!x.locked&&x.entries[p.id]).sort((a,b)=>b.end.localeCompare(a.end)).slice(0,1))syncDatesToEntry(draft.entries[p.id],n,r);}
 }));$('#contract-form [data-cancel-contract]').onclick=()=>$('#modal').close();if(existing){$('#contract-delete').onclick=()=>registryDelete(r.id);$('#registry-extension').onclick=()=>registryExtensionDialog(r.id);}bindRegistryMasters();bindSegmentEditor();bindPersonnelEditor();}
function syncDatesToEntry(e,r,before={}){for(const [target,key]of [['note','note'],['deliveryDate','deliveryDate'],['acceptanceDate','acceptanceDate'],['paymentDate','finalPaymentDate'],['payment','payment']])if(r[key]!==before[key])e[target]=r[key]||'';if(e.payment==='เบิกจ่ายแล้ว'){if(!e.paymentDate)throw Error('รายงานฉบับร่างที่เบิกจ่ายแล้วต้องมีวันที่เบิกจ่าย');e.note=paymentNote(e);}}
function bindRegistryMasters(){const form=$('#contract-form');const inputFor=key=>form.querySelector(`[data-master-key="${key}"]`);const refresh=()=>{const code=state.workCodes.find(x=>x.name===inputFor('workCodes').value.trim()),type=state.workTypes.find(x=>x.name===inputFor('workTypes').value.trim());$$('#contract-form [data-master-key]').forEach(input=>{const key=input.dataset.masterKey;let rows=state[key].filter(x=>!x.deletedAt);if(key==='workNames')rows=rows.filter(x=>(!type||x.typeId===type.id)&&(!code||x.codeIds?.includes(code.id)));const text=input.value.trim();$('#registry-list-'+key).innerHTML=rows.filter(x=>!text||x.name.toLowerCase().includes(text.toLowerCase())).map(x=>`<option value="${esc(x.name)}">`).join('');form.querySelector(`[data-registry-add-master="${key}"]`).hidden=!text||state[key].some(x=>x.name===text&&!x.archived);});};
 $$('#contract-form [data-master-key]').forEach(input=>{input.oninput=refresh;input.onchange=()=>{if(input.dataset.masterKey==='workCodes'){const code=state.workCodes.find(x=>x.name===input.value.trim()),jobs=state.workNames.filter(x=>!x.archived&&x.codeIds?.includes(code?.id));if(jobs.length===1){inputFor('workNames').value=jobs[0].name;inputFor('workTypes').value=state.workTypes.find(x=>x.id===jobs[0].typeId)?.name||inputFor('workTypes').value;}}refresh();};});
 $$('#contract-form [data-registry-add-master]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const key=b.dataset.registryAddMaster,input=inputFor(key),name=input.value.trim();await mutate('เพิ่มรายการพื้นฐาน '+name,s=>{if(!name||s[key].some(x=>x.name===name&&!x.archived))throw Error('ชื่อว่างหรือมีอยู่แล้ว');const archivedItem=s[key].find(x=>x.name===name&&x.archived);if(archivedItem){archivedItem.archived=false;return;}const item={id:key.toUpperCase()+'-'+uid(),name,archived:false};if(key==='workNames'){item.typeId=s.workTypes.find(x=>x.name===inputFor('workTypes').value.trim())?.id||'';const code=s.workCodes.find(x=>x.name===inputFor('workCodes').value.trim());if(!code)throw Error('กรุณาเลือกรหัสงานก่อนเพิ่มชื่องาน');if(s.workNames.some(w=>w.codeIds?.includes(code.id)))throw Error('รหัสงานนี้จับคู่กับชื่องานอื่นแล้ว');item.codeIds=[code.id];}s[key].push(item);});refresh();input.focus();}catch(e){showFormError(form,e.message);}finally{b.disabled=false;}});refresh();}
function registryExtensionDialog(id){const r=state.contractRegistry.find(x=>x.id===id);modal('บันทึกขยายอายุสัญญา · '+r.contract,`<form><div class="form-grid">${field('เลขหนังสืออนุมัติ','reference','','text','required')}${field('วันที่อนุมัติ','approvedAt',today(),'date','required')}${field('จำนวนวันเพิ่ม','days',7,'number','min="1" step="1" required')}${field('วันสิ้นสุดใหม่','end',addDays(r.end,7),'date','required')}</div>${buttons('บันทึกการอนุมัติ')}</form>`,f=>mutate('ขยายสัญญา '+r.contract,s=>{const n=s.contractRegistry.find(x=>x.id===id),d=+f.get('days');if(!Number.isInteger(d)||d<1||addDays(n.end,d)!==f.get('end'))throw Error('วันสิ้นสุดใหม่ต้องเท่ากับวันเดิมบวกวันขยาย');if(n.extensions.some(x=>x.reference===String(f.get('reference')).trim()))throw Error('เลขหนังสือซ้ำ');n.extensions.push({id:uid(),days:d,end:f.get('end'),reference:String(f.get('reference')).trim(),approvedAt:f.get('approvedAt'),approved:true});n.end=f.get('end');n.updatedAt=new Date().toISOString();const p=s.projects.find(x=>x.id===n.projectId);if(p){Object.assign(p,projectFromRegistry(s,n));if(!n.deletedAt)delete p.deletedAt;};}));$('#modal [name=days]').oninput=e=>$('#modal [name=end]').value=addDays(r.end,+e.target.value||0);}
async function ensureFirstWeekly(){if(view!=='weekly')return;const found=state.reports.find(r=>reportMatchesScope(state,r,year,funding));selected=found?.id;}
function weeklySummary(rows){const labels=[['all','ทั้งหมด'],['ongoing','กำลังดำเนินการ'],['deliver','รอส่งมอบงาน'],['pay','รอเบิกจ่าย'],['paid','เบิกจ่ายแล้ว']];return `<section class="register-summary" aria-label="สรุปสถานะสัญญา"><div class="summary-title"><h2>สัญญาในสัปดาห์นี้</h2><span>${esc(fundingName(state,funding))} · ${year}</span></div><div class="summary-items">${labels.map(([key,label])=>`<button data-filter="${key}" class="summary-count ${filter===key?'selected':''}"><span>${label}</span><strong>${key==='all'?rows.length:rows.filter(x=>statusKey(x.e)===key).length}</strong></button>`).join('')}</div></section>`;}
function contractDatesDialog(pid){const r=report(),e=r.entries[pid],p=projectAt(state,r,pid);modal('วันที่ส่งมอบ ตรวจรับ และเบิกจ่าย · '+p.contract,`<form><div class="form-grid">${field('วันส่งมอบงาน','deliveryDate',e.deliveryDate||'','date')}${field('วันตรวจรับงาน','acceptanceDate',e.acceptanceDate||'','date')}${field('วันที่เบิกจ่าย','paymentDate',e.paymentDate||'','date',e.payment==='เบิกจ่ายแล้ว'?'required':'')}</div>${buttons('บันทึกวันที่')}</form>`,async f=>{const patch=contractDatePatch(e,Object.fromEntries(['deliveryDate','acceptanceDate','paymentDate'].map(k=>[k,String(f.get(k)||'')])));if(!Object.keys(patch).length)throw Error('ยังไม่มีข้อมูลเปลี่ยนแปลง');validateDates({...e,...patch});if(r.locked)await saveAmendment(r.id,{[pid]:patch});else await mutate('บันทึกวันที่สัญญา',s=>{const entry=s.reports.find(x=>x.id===r.id).entries[pid];Object.assign(entry,patch);if(entry.payment==='เบิกจ่ายแล้ว')entry.note=paymentNote(entry);entry.confirmed=false;syncContractDates(s,pid,entry,[...Object.keys(patch),...(entry.payment==='เบิกจ่ายแล้ว'?['note']:[])]);});});}
function bindRegistry(){bindSortHeaders();$$('[data-budget-filter]').forEach(b=>b.onclick=()=>{budgetFilter=b.dataset.budgetFilter;page=1;render();});$$('[data-registry-view]').forEach(b=>b.onclick=e=>{e.stopPropagation();registryDetailDialog(b.dataset.registryView);});$$('[data-registry-edit]').forEach(b=>b.onclick=e=>{e.stopPropagation();registryEditDialog(b.dataset.registryEdit);});$$('[data-registry-delete]').forEach(b=>b.onclick=e=>{e.stopPropagation();registryDelete(b.dataset.registryDelete);});$$('[data-registry-row]').forEach(row=>{row.onclick=e=>{if(!e.target.closest('button'))registryDetailDialog(row.dataset.registryRow);};row.onkeydown=e=>{if(e.target===row&&['Enter',' '].includes(e.key)){e.preventDefault();registryDetailDialog(row.dataset.registryRow);}};});$('#registry-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;page=1;render();$('#registry-search').focus();$('#registry-search').setSelectionRange(pos,pos);});$$('[data-registry-page]').forEach(b=>b.onclick=()=>{page=+b.dataset.registryPage;render();});$$('[data-contract-dates]').forEach(b=>b.onclick=()=>contractDatesDialog(b.dataset.contractDates));}
function bindSortHeaders(){$$('[data-sort-scope]').forEach(b=>b.onclick=()=>{const sort=b.dataset.sortScope==='registry'?registrySort:weeklySort;sort.dir=sort.key===b.dataset.sortKey?-sort.dir:1;sort.key=b.dataset.sortKey;page=1;render();});}

function registryImportDialog(excel=false){let records=[],preview=[],sourceName='';modal(excel?'นำเข้า Excel แบบ ก-3':'นำเข้า Excel ทะเบียนสัญญา',`<form id="registry-import"><div class="form-grid">${selectField('กลุ่มงบ','funding',state.fundingSources.map(x=>({value:x.id,label:x.name})),funding)}${selectField('ปีงบประมาณ','year',state.years,year)}<label class="field wide">${excel?'ไฟล์ Excel แบบ ก-3 (.xlsx)':'ไฟล์ Excel (.xlsx) หรือ CSV เดิม'}<input id="registry-file" type="file" accept="${excel?'.xlsx':'.xlsx,.csv'}" required></label></div><p class="hint">จำเป็น: เลขสัญญา ชื่องาน เริ่มต้นสัญญา วันสิ้นสุดปัจจุบัน ระยะเวลาเดิม (วัน) · ปีและกลุ่มงบเว้นว่างเพื่อใช้ค่าที่เลือกได้ · จับคู่ด้วย ID ก่อน แล้วจึงเลขสัญญาเมื่อไม่มี ID · รายการนอกไฟล์คงเดิม · ช่องว่างคงค่าเดิม · รายการใหม่เว้น ID และ workspace_id ว่าง ระบบสร้าง ID และใช้พื้นที่ปัจจุบันอัตโนมัติ · แบบ ก-3 ใช้วงเงินสัญญาแยกจาก PO · รวมโครงการเป็นยอดเบิกจ่ายสะสม · จับคู่ ID Code ก่อนเลขสัญญา</p><button type="button" class="btn primary" id="load-registry-file">${'อ่านไฟล์และตรวจข้อมูล'}</button><div id="registry-import-preview"></div><p class="form-error" role="alert"></p></form>`);const form=$('#registry-import');form.elements.funding.value=funding;form.elements.year.value=String(year);const show=()=>{preview=previewRegistryImport(state,records,+form.elements.year.value,form.elements.funding.value).map(x=>({...x,changes:csvPreviewChanges(state,'registry',x)}));const duplicates=preview.filter(x=>x.duplicateId||x.fileDuplicate).length,errors=preview.filter(x=>x.errors.length).length;$('#registry-import-preview').innerHTML=`<div class="notice">อ่านได้ ${records.length} รายการ · ซ้ำ ${duplicates} · มีปัญหา ${errors} · เพิ่มประเภทงานจากไฟล์ ${new Set(preview.map(x=>x.record.pendingWorkTypeName).filter(Boolean)).size} รายการ</div><div class="table-scroll import-scroll"><table data-selection-key="import-registry" data-selection-ids="${esc(JSON.stringify(preview.map(x=>String(x.index))))}"><thead><tr><th>แถว / สัญญา</th><th>ชื่องาน</th><th>ตรวจสอบ</th><th>การนำเข้า</th></tr></thead><tbody>${preview.map(item=>`<tr data-select-id="${item.index}"><td>${item.record.sourceRow||item.record.csvRow||item.index+1}<br>${esc(item.record.contract)}${item.record.id?`<br><small class="sub">${esc(item.record.id)}</small>`:''}</td><td>${esc(item.record.title)}${!item.errors.length&&!item.fileDuplicate?csvChangeHTML(item.changes,state):''}</td><td>${esc(item.errors.join(' | ')||((item.duplicateId||item.fileDuplicate)?'เลขสัญญาซ้ำ':'')||(Array.isArray(item.record.warnings)?item.record.warnings.join(' | '):String(item.record.warnings||'')))}</td><td>${item.duplicateId||item.fileDuplicate||item.errors.length?`<select data-import-choice="${item.index}">${!item.errors.length?'<option value="overwrite">บันทึกทับค่าเดิม</option>':''}<option value="skip" ${item.fileDuplicate?'selected':''}>ข้าม</option></select>`:'เพิ่มใหม่'}</td></tr>`).join('')}</tbody></table></div><div class="dialog-actions"><button type="button" class="btn" id="download-registry-csv">ดาวน์โหลด Excel</button><button type="button" class="btn primary" id="commit-registry-import">นำเข้าเพิ่ม / อัปเดตทะเบียน</button></div>`;selectionAdapters.set('import-registry',ids=>download(registryXLSX(records.filter((_,index)=>ids.includes(String(index)))),'ตัวอย่างทะเบียนที่เลือก.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'));mountSelections();$('#download-registry-csv').onclick=()=>download(registryXLSX(records),'ทะเบียนสัญญา.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');$('#commit-registry-import').onclick=async()=>{const b=$('#commit-registry-import');await commitCSVForm(b,async()=>{const chosen=new Set(selectionFor('import-registry',preview.map(x=>x.index))),choices={};for(const item of preview)if(!chosen.has(String(item.index)))choices[item.index]='skip';$$('[data-import-choice]').forEach(x=>{if(chosen.has(x.dataset.importChoice))choices[+x.dataset.importChoice]=x.value;});let result;await mutate('นำเข้าทะเบียนสัญญา',s=>{const prior=cloneForMutation(s);result=applyRegistryImport(s,preview,choices);Object.assign(s,result.state);if(result.added+result.updated)captureImportResult(s,'contractRegistry',prior,sourceName);},{fileName:sourceName||'ทะเบียนสัญญา.csv',format:/\.xlsx$/i.test(sourceName)?'XLSX':'CSV'});year=+form.elements.year.value;funding=form.elements.funding.value;$('#modal').close();render();toast(`นำเข้าแล้ว: เพิ่ม ${result.added} ทับ ${result.updated} ข้าม ${result.skipped} ไม่เปลี่ยน ${result.unchanged}`);},e=>toast(e.message,true));};};$('#load-registry-file').onclick=async()=>{const b=$('#load-registry-file');b.disabled=true;try{const file=$('#registry-file').files[0];if(!file)throw Error('เลือกไฟล์ก่อน');if(/\.xlsx$/i.test(file.name)){const result=await readG3Workbook(await file.arrayBuffer(),excel?'plannet':'registry');records=result.records;if(result.fiscalYear){if(![...form.elements.year.options].some(o=>+o.value===result.fiscalYear))form.elements.year.add(new Option(String(result.fiscalYear),String(result.fiscalYear)));form.elements.year.value=String(result.fiscalYear);}}else{if(file.size>10000000)throw Error('CSV ต้องไม่เกิน 10 MB');records=parseRegistryCSV(await file.text());}sourceName=file.name;tableSelections.delete('import-registry');show();}catch(e){showFormError(form,e.message);}finally{b.disabled=false;}};$('#registry-file').onchange=()=>{records=[];preview=[];sourceName='';$('#registry-import-preview').innerHTML='';};form.elements.year.onchange=()=>records.length&&show();form.elements.funding.onchange=()=>records.length&&show();}

